// Built-in card data. Personal edits and progress are saved by the application.
const DATABASE_INTRO_CARDS = [
  ["Probleme traditioneller Dateiverwaltung", "Welche Probleme hat die traditionelle Dateiverwaltung?", "• Programm-Daten-Abhängigkeit\n• Fehlende Anfragesprache\n• Schlechte Datenmodellierung\n• Redundanz", 1],
  ["Programm-Daten-Abhängigkeit", "Was bedeutet Programm-Daten-Abhängigkeit?", "Die Speicherung und Interpretation der Daten hängen vom jeweiligen Programm und dessen Metadaten ab. Andere Programme können diese Daten daher nicht ohne Weiteres direkt interpretieren.", 1],
  ["Datenbank (DB)", "Was ist eine Datenbank?", "Eine Datenbank ist eine Sammlung logisch zusammengehöriger Daten, die persistent, also dauerhaft über die Lebensdauer eines Anwendungsprozesses hinaus, gespeichert wird.", 1],
  ["Datenbank-Management-System (DBMS)", "Was ist ein DBMS? Nennen Sie Beispiele.", "Ein DBMS ist ein Softwarepaket zur Verwaltung einer Datenbank, etwa zum Einfügen, Löschen und Abfragen von Daten. Es stellt die Schnittstelle zwischen Anwendungen und Datenbank bereit.\n\nBeispiele: Oracle Database, Microsoft SQL Server, MariaDB und MySQL.", 1],
  ["Datenbanksystem (DBS)", "Woraus besteht ein Datenbanksystem?", "Ein Datenbanksystem kombiniert ein DBMS mit einer anwendungsspezifischen Datenbank einschließlich der benötigten Metadaten.\n\nDBS = DBMS + DB (einschließlich Metadaten).", 1],
  ["Datenmodell", "Welche Konzepte umfasst ein Datenmodell?", "Ein Datenmodell enthält Konzepte zur Beschreibung von:\n• Daten und ihren Beziehungen,\n• der Bedeutung der Daten und Integritätsbedingungen,\n• Operationen zur Verhaltensmodellierung.", 1],
  ["Datenbankmodell", "Was ist ein Datenbankmodell? Nennen Sie Beispiele.", "Ein Datenbankmodell ist ein spezielles Datenmodell zur Beschreibung einer Datenbank. Beispiele sind das hierarchische, Netzwerk-, relationale, objektorientierte und objektrelationale Modell.", 1],
  ["Datenbankschema", "Was beschreibt ein Datenbankschema?", "Ein Datenbankschema beschreibt eine konkrete Datenbank mit den Konzepten eines Datenbankmodells. Es legt die Struktur und die Einschränkungen der Datenbank fest.", 1],
  ["Datenmodell, Datenbankmodell und Schema", "Wie hängen Datenmodell, Datenbankmodell und Datenbankschema zusammen?", "Ein Datenmodell stellt allgemeine Beschreibungskonzepte bereit. Ein Datenbankmodell spezialisiert diese für Datenbanken. Ein Datenbankschema verwendet die Konzepte eines Datenbankmodells, um die Struktur und Einschränkungen einer konkreten Datenbank festzulegen.", 2],
  ["Datenbanksprachen", "Welche vier Arten von Datenbanksprachen unterscheidet der Wissenskatalog?", "• DDL — Data Definition Language: Schemata erstellen und ändern.\n• DML — Data Manipulation Language: Daten einfügen, löschen und ändern.\n• QL — Query Language: Daten abfragen.\n• DBPL — Database Programming Language: Datenbankanwendungen programmieren.", 2],
  ["DDL", "Wozu dient die Data Definition Language (DDL)?", "DDL dient zum Erstellen und Modifizieren eines Datenbankschemas, also zur Definition und Änderung der Datenbankstruktur.", 2],
  ["DML und QL", "Wie unterscheiden sich DML und QL in der Einteilung des Wissenskatalogs?", "DML verändert Daten durch Einfügen, Löschen und Ändern. QL dient zum Abfragen von Daten.", 2],
  ["DBPL", "Wozu dient eine Database Programming Language (DBPL)?", "Eine DBPL dient zum Programmieren von Datenbankanwendungen.", 2],
  ["Datenbanknutzer", "Welche drei Gruppen von Datenbanknutzern werden unterschieden?", "• Endnutzer\n• Datenbank-Anwendungsprogrammierer\n• Datenbankadministratoren", 2],
  ["Endnutzer", "Wie greifen Endnutzer auf eine Datenbank zu?", "Endnutzer verwenden Anwendungsprogramme, beispielsweise über Formulare.", 2],
  ["DB-Anwendungsprogrammierer", "Welche Aufgaben und Sprachen gehören zur Datenbank-Anwendungsprogrammierung?", "Anwendungsprogrammierer entwerfen Formulare, erzeugen und verwenden Nutzersichten und implementieren Anwendungen. Sie verwenden Programmiersprachen (PL), DBPL, DML und QL.", 2],
  ["Datenbankadministrator", "Welche Aufgaben hat ein Datenbankadministrator?", "• Logische und physische Schemata entwerfen\n• Integritätsbedingungen festlegen\n• Sicherheit und Autorisierung verwalten\n• Verfügbarkeit durch Sicherung und Wiederherstellung gewährleisten\n• Leistung überwachen und Tuning durchführen\n\nDazu verwendet er unter anderem DDL, DML und QL.", 2],
  ["3-Ebenen-Schema-Architektur", "Welche Ebenen umfasst die 3-Ebenen-Schema-Architektur?", "Die Architektur trennt drei Ebenen:\n• Externe Schemata: Sichten einzelner Nutzer oder Anwendungen\n• Konzeptuelles Schema: logische Beschreibung der gesamten Datenbank\n• Internes Schema: physische Darstellung der Datenbank", 2],
  ["Externes Schema", "Was beschreibt ein externes Schema?", "Ein externes Schema beschreibt eine Nutzersicht für eine bestimmte Anwendung, meist einen Ausschnitt der Datenbank. Es ist auf dem konzeptuellen Schema definiert. Es kann mehrere externe Schemata geben.", 2],
  ["Konzeptuelles Schema", "Was beschreibt das konzeptuelle Schema?", "Es beschreibt die gesamte Datenbank unter Verwendung eines Datenbankmodells, insbesondere Struktur, Integritätsbedingungen und Autorisierung. Es ist unabhängig von Implementierungsdetails.", 2],
  ["Internes Schema", "Was beschreibt das interne Schema?", "Es beschreibt die physische Darstellung und Speicherung der Datenbank, abhängig vom Betriebssystem. Dazu gehört beispielsweise die Anlage von Indizes.", 2],
  ["Physische Datenunabhängigkeit", "Was bedeutet physische Datenunabhängigkeit?", "Das konzeptuelle Schema ist unabhängig von Änderungen des internen Schemas. Die physische Speicherung oder Implementierung kann geändert werden, ohne das konzeptuelle Schema ändern zu müssen.", 2],
  ["Logische Datenunabhängigkeit", "Was bedeutet logische Datenunabhängigkeit?", "Externe und konzeptuelle Schemata sind entkoppelt: Bestimmte Änderungen des konzeptuellen Schemas erfordern keine Änderung externer Schemata. Umgekehrt können externe Schemata geändert werden, ohne das konzeptuelle Schema zu ändern.", 3],
  ["Datenunabhängigkeit: Ebenen", "Zwischen welchen Ebenen liegen logische und physische Datenunabhängigkeit?", "• Logische Datenunabhängigkeit: zwischen externen Schemata und konzeptuellem Schema.\n• Physische Datenunabhängigkeit: zwischen konzeptuellem und internem Schema.", 3],
  ["Neun Anforderungen (Codd’sche Regeln im Katalog)", "Welche neun Anforderungen führt der Wissenskatalog unter „Codd’schen Regeln“ auf?", "1. Integration\n2. Operationen\n3. Katalog\n4. Nutzersichten\n5. Konsistenzüberwachung\n6. Zugriffskontrolle\n7. Transaktionen\n8. Synchronisation\n9. Datensicherung und Wiederherstellung", 3],
  ["Integration", "Was bedeutet Integration bei der Datenverwaltung?", "Integration bedeutet eine einheitliche Datenverwaltung mit dem Ziel, redundante Datenhaltung zu vermeiden.", 3],
  ["Katalog (Data Dictionary)", "Was enthält der Datenbankkatalog?", "Der Katalog enthält Metadaten, also Daten über Daten. Dazu gehören insbesondere Schemadaten, die die Struktur der Datenbank beschreiben.", 3],
  ["Nutzersichten", "Was sind Nutzersichten auf eine Datenbank?", "Nutzersichten stellen unterschiedliche Sichten auf die Datenbank bereit. Im relationalen Kontext sind dies virtuelle Relationen.", 3],
  ["Konsistenz und Integrität", "Wie unterscheidet der Wissenskatalog Konsistenz und Integrität?", "Konsistenz wird hier als Übereinstimmung aller Kopien derselben Daten im System beschrieben. Integrität bezeichnet die semantische Korrektheit und Vollständigkeit der Daten.", 3],
  ["Zugriffskontrolle", "Was gewährleistet die Zugriffskontrolle?", "Nur berechtigte beziehungsweise autorisierte Nutzer dürfen auf die Datenbank und die für sie freigegebenen Daten zugreifen.", 3],
  ["Transaktion", "Was ist eine Transaktion?", "Eine Transaktion ist eine atomare, logische Einheit von Datenbankoperationen. Sie wird vollständig oder gar nicht ausgeführt und überführt die Datenbank von einem konsistenten Zustand in einen konsistenten, gegebenenfalls veränderten Zustand.", 3],
  ["Synchronisation", "Wozu dient Synchronisation im Mehrbenutzerbetrieb?", "Synchronisation koordiniert konkurrierende Zugriffe mehrerer Nutzer, um dadurch verursachte Inkonsistenzen zu vermeiden.", 3],
  ["Datensicherung und Wiederherstellung", "Wozu dienen Datensicherung und Wiederherstellung?", "Regelmäßige Sicherungen schützen vor Datenverlust. Mithilfe gesicherter Daten kann die Datenbank nach einem Ausfall wiederhergestellt werden.", 3]
].map(([term,question,definition,page],i)=>({id:"doc_db_intro_"+String(i+1).padStart(3,"0"),term,question,definition,note:"DB-Wissenskatalog.pdf • Kapitel 1: Einführende Begriffe • S. "+page,subject:"Datenbanken",topic:"Einführende Begriffe",sourceStatus:"ready"}));

