DATABASE_INTRO_CARDS.push(...[
  {"id": "doc_db_vl00_001", "term": "Weitere Nachteile der Dateiverwaltung", "question": "Welche zusätzlichen Probleme entstehen bei Dateiverwaltung ohne DBMS?", "definition": "Neben Redundanz und Programm-Daten-Abhängigkeit fehlen häufig gemeinsame Metadaten, wirksame Zugriffskontrolle, koordinierter Mehrbenutzerzugriff und zuverlässige Sicherung. Verschiedene Kopien derselben Information können auseinanderlaufen.", "subject": "Datenbanken", "topic": "Einführung: Grundbegriffe und Dateiverwaltung", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_002", "term": "Nutzen eines DBMS", "question": "Welche Vorteile bietet ein DBMS gegenüber getrennten Anwendungsdateien?", "definition": "Es integriert Daten für mehrere Anwendungen, erzwingt Integritätsbedingungen, kontrolliert Zugriffe und koordiniert konkurrierende Änderungen. Hinzu kommen Anfrageoptimierung, Datenunabhängigkeit, Wiederherstellung, Metadatenverwaltung und standardisierte Schnittstellen.", "subject": "Datenbanken", "topic": "Einführung: Grundbegriffe und Dateiverwaltung", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–8 bis 1–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_003", "term": "Schema und Datenbankzustand", "question": "Wie unterscheiden sich ein Schema und ein Datenbankzustand?", "definition": "Das Schema beschreibt die erlaubte Struktur und Bedingungen; ein Zustand enthält die aktuell gespeicherten Daten, die diese Bedingungen erfüllen müssen. Beispiel: Die Spalten einer Angestelltentabelle gehören zum Schema, ihre derzeitigen Zeilen zum Zustand.", "subject": "Datenbanken", "topic": "Einführung: Modelle, Schemata und Sprachen", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–11 bis 1–15", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_004", "term": "Entwicklung der Datenmodelle", "question": "Welche Datenmodellfamilien werden in der Einführung eingeordnet?", "definition": "Hierarchische und Netzwerkmodelle gehören zur frühen Generation. Das relationale Modell ordnet Daten als Relationen. Spätere Ansätze umfassen objektorientierte, objektrelationale, deduktive und semistrukturierte Modelle.", "subject": "Datenbanken", "topic": "Einführung: Modelle, Schemata und Sprachen", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–12 bis 1–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_005", "term": "Relationale Darstellung in der Einführung", "question": "Wie stellt eine relationale Datenbank Daten und Zusammenhänge dar?", "definition": "Daten stehen in Tabellen mit benannten Spalten und Zeilen. Übereinstimmende Identifikationswerte verbinden Tabellen logisch. Im Weinkellerbeispiel wählt eine SELECT-Anfrage bestimmte Weine und Spalten aus, während INSERT, UPDATE und DELETE den Bestand ändern.", "subject": "Datenbanken", "topic": "Einführung: Relationale Beispieldatenbank", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–19 bis 1–22", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_006", "term": "Anfragen über drei Schemaebenen", "question": "Wie wird eine Nutzeranfrage durch die drei Schemaebenen vermittelt?", "definition": "Eine Anwendung formuliert ihre Anfrage auf einem externen Schema. Abbildungen verbinden dieses mit dem konzeptuellen und anschließend dem internen Schema. Ergebnisse werden zurück in der Nutzersicht dargestellt; die Trennung verbirgt Speicherungsdetails.", "subject": "Datenbanken", "topic": "Einführung: Architektur und Datenunabhängigkeit", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–24 bis 1–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_007", "term": "Komponenten der Anfrageverarbeitung", "question": "Welche Aufgabe haben DDL-Prozessor, Anfrageprozessor, Optimierer und Laufzeitmanager?", "definition": "Der DDL-Prozessor verarbeitet Schemadefinitionen und Metadaten. Der DML-/QL-Prozessor übersetzt Änderungen und Anfragen. Der Optimierer sucht einen günstigen Ausführungsplan; der Laufzeitmanager führt ihn unter Beachtung von Sicherheits- und Konsistenzbedingungen aus.", "subject": "Datenbanken", "topic": "Einführung: Systemarchitektur und Einordnung", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–37", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_008", "term": "Historische Einordnung von DBMS", "question": "Welche Entwicklung und historischen Systembeispiele nennt die Vorlesung?", "definition": "Auf Dateiverwaltung und Dateiverwaltungssysteme folgten hierarchische und Netzwerk-DBMS, danach relationale und weitere spezialisierte Modelle. Historische Beispiele: IMS für hierarchische Systeme, IDMS/UDS für Netzwerkmodelle sowie Oracle, DB2 und SQL Server für relationale Systeme. Die Einordnung beschreibt die Vorlesungsfolie, keine aktuelle Marktübersicht.", "subject": "Datenbanken", "topic": "Einführung: Systemarchitektur und Einordnung", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–38 bis 1–39", "sourceStatus": "ready"},
  {"id": "doc_db_vl00_009", "term": "Anwendungsgebiete von Datenbanken", "question": "Welche typischen Datenbankanwendungen nennt die Vorlesung?", "definition": "Banken, Versicherungen, Personalverwaltung, E-Commerce, Polizei-, Universitäts- und Bibliotheksinformationssysteme. Sie verwalten viele zusammengehörige Objekte, die mehrere Anwendungen gemeinsam nutzen.", "subject": "Datenbanken", "topic": "Einführung: Systemarchitektur und Einordnung", "note": "DB.pdf • Kapitel 1: Einführung • Folien 1–40", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_001", "term": "COMPANY-Beispielschema", "question": "Welche Tabellen und Verknüpfungen bilden die COMPANY-Beispieldatenbank?", "definition": "EMPLOYEE beschreibt Angestellte, DEPARTMENT Abteilungen, PROJECT Projekte, WORKS_ON Projektmitarbeit, DEPENDENT Angehörige und DEPT_LOCATIONS Abteilungsorte. EMPLOYEE.DNO verweist auf DEPARTMENT.DNUMBER; WORKS_ON verbindet ESSN mit EMPLOYEE.SSN und PNO mit PROJECT.PNUMBER.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Beispielschema und SQL-Modell", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–2 bis 2–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_002", "term": "SQL und Standardisierung", "question": "Was ist SQL, und warum garantiert der Standard keine identischen DBMS?", "definition": "SQL bedeutet Structured Query Language. Der Standard umfasst Datenmodell, Definition, Änderung, Abfrage sowie Integrität und weitere Konzepte. Implementierungen unterstützen unterschiedliche Teilmengen und Erweiterungen. Die Vorlesung konzentriert sich auf SQL-92; SQL:1999 ergänzt unter anderem Rekursion und Trigger.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Beispielschema und SQL-Modell", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–7 bis 2–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_003", "term": "Mengen- und Multimengensemantik in SQL", "question": "Wie unterscheiden sich SQL-Tabellen von mathematischen Relationen?", "definition": "SQL arbeitet standardmäßig mit Multimengen: Gleiche Ergebniszeilen dürfen mehrfach auftreten. Mathematische Relationen sind Mengen ohne Duplikate. `SELECT DISTINCT DNO FROM EMPLOYEE;` entfernt wiederholte Abteilungsnummern; ohne DISTINCT bleiben sie erhalten. Eine Reihenfolge ist erst mit ORDER BY festgelegt.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Beispielschema und SQL-Modell", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–10, 2–49 bis 2–50", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_004", "term": "CREATE TABLE", "question": "Wie definiert man eine Tabelle mit Primär- und Fremdschlüssel?", "definition": "Beispiel: `CREATE TABLE EMPLOYEE (SSN CHAR(9) PRIMARY KEY, LNAME VARCHAR(15) NOT NULL, DNO INT, FOREIGN KEY (DNO) REFERENCES DEPARTMENT(DNUMBER));` Spalten legen Namen und Typen fest; Bedingungen beschränken zulässige Daten. Referenzierte Schlüssel müssen geeignet eindeutig sein.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–11 bis 2–12", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_005", "term": "Numerische SQL-Datentypen", "question": "Welche numerischen Typen und welche Bedeutung hat DECIMAL(p,s)?", "definition": "INTEGER/SMALLINT speichern ganze Zahlen; REAL/FLOAT/DOUBLE PRECISION approximative Gleitkommazahlen. DECIMAL(p,s) beziehungsweise NUMERIC(p,s) beschreiben exakte Dezimalzahlen mit Präzision p und s Nachkommastellen. Für Geldbeträge ist eine exakte Dezimaldarstellung häufig geeigneter als Gleitkomma.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datentypen und Domänen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_006", "term": "Zeichen- und Bitketten", "question": "Wie unterscheiden sich CHAR(n), VARCHAR(n) und Bitketten?", "definition": "CHAR(n) hat feste Zeichenlänge; VARCHAR(n) eine variable Länge bis zur angegebenen Grenze. BIT(n) beschreibt eine Bitkette fester Länge, BIT VARYING(n) eine variable Bitkette im auf den Folien behandelten SQL-Standard.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datentypen und Domänen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_007", "term": "Datum und Zeit", "question": "Was repräsentieren DATE, TIME und TIMESTAMP?", "definition": "DATE speichert ein Datum, TIME eine Uhrzeit und TIMESTAMP Datum mit Uhrzeit. Eine Präzisionsangabe kann die Sekundenbruchteile bestimmen; für entsprechende Zeittypen behandelt die Vorlesung auch WITH TIME ZONE. Übliche Literale sind etwa `DATE '2026-10-27'` und `TIME '14:30:00'`.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datentypen und Domänen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–15", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_008", "term": "Benutzerdefinierte Domäne", "question": "Wozu dient CREATE DOMAIN?", "definition": "Eine Domäne benennt einen wiederverwendbaren Wertebereich und kann Bedingungen enthalten. Beispiel: `CREATE DOMAIN SSN_TYPE AS CHAR(9);` Anschließend kann eine Spalte mit `SSN SSN_TYPE` deklariert werden. Das verbessert Lesbarkeit und zentrale Pflege.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datentypen und Domänen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–16", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_009", "term": "NOT NULL, DEFAULT und CHECK", "question": "Was bewirken NOT NULL, DEFAULT und CHECK?", "definition": "NOT NULL verbietet fehlende Werte; DEFAULT liefert einen Vorgabewert, wenn keine explizite Angabe erfolgt. CHECK beschränkt zulässige Werte, etwa `SALARY DECIMAL(10,2) CHECK (SALARY > 0)`. CHECK allein verbietet NULL nicht: Für zwingend vorhandene positive Werte ist zusätzlich NOT NULL erforderlich.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–17 bis 2–18", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_010", "term": "PRIMARY KEY und UNIQUE", "question": "Wie unterscheiden sich PRIMARY KEY und UNIQUE?", "definition": "PRIMARY KEY kennzeichnet den gewählten Identifikationsschlüssel, ist eindeutig und verbietet NULL in seinen Attributen. UNIQUE formuliert weitere Eindeutigkeitsbedingungen, etwa alternative Schlüssel. Beide können mehrere Spalten umfassen. Die Behandlung von NULL bei UNIQUE hängt vom DBMS beziehungsweise der gewählten Definition ab.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–19", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_011", "term": "FOREIGN KEY", "question": "Wie formuliert man referentielle Integrität in SQL?", "definition": "Mit `FOREIGN KEY (DNO) REFERENCES DEPARTMENT(DNUMBER)`. Nichtleere Referenzwerte müssen auf vorhandene Schlüsselwerte zeigen. Auch mehrspaltige und selbstreferenzierende Fremdschlüssel sind möglich; das Referenzziel muss eindeutig sein.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–19 bis 2–21", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_012", "term": "Referenzaktionen", "question": "Was bedeuten CASCADE, SET NULL und SET DEFAULT bei ON DELETE beziehungsweise ON UPDATE?", "definition": "Sie regeln Änderungen an referenzierten Zeilen: CASCADE löscht abhängige Zeilen beziehungsweise passt Referenzwerte an; SET NULL setzt den Fremdschlüssel auf NULL; SET DEFAULT verwendet seinen Vorgabewert. Die Aktion muss weiterhin alle Bedingungen erfüllen. Fehlt eine zulässige Reparatur, wird die Änderung abgelehnt.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–20 bis 2–26", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_013", "term": "Referenzaktionen: Beispiel", "question": "Was geschieht beim Löschen einer Abteilung mit abhängigen Angestellten?", "definition": "Bei ON DELETE CASCADE werden die verweisenden EMPLOYEE-Zeilen gelöscht. Bei ON DELETE SET NULL bleiben sie erhalten, aber DNO wird NULL. Bei SET DEFAULT muss der Vorgabewert als Referenz zulässig sein. Die passende Aktion hängt von der fachlichen Bedeutung ab.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–23 bis 2–26", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_014", "term": "DROP TABLE und ALTER TABLE", "question": "Was unterscheidet DROP TABLE von ALTER TABLE und DELETE?", "definition": "DROP TABLE entfernt Tabelle und Daten. ALTER TABLE verändert die Struktur, zum Beispiel `ALTER TABLE EMPLOYEE ADD JOB VARCHAR(20);`. DELETE entfernt Zeilen, lässt aber das Schema bestehen. Abhängigkeiten und Integritätsbedingungen können die Ausführung einschränken.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: DDL und Integritätsbedingungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–27 bis 2–29", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_015", "term": "INSERT", "question": "Wie fügt man eine Zeile ein, und warum ist eine Spaltenliste sinnvoll?", "definition": "`INSERT INTO EMPLOYEE (SSN, LNAME, DNO) VALUES ('123456789', 'Meyer', 5);` Die Spaltenliste ordnet Werte eindeutig zu. Nicht genannte Spalten erhalten zulässige Standardwerte beziehungsweise NULL; zwingend benötigte Werte ohne Vorgabe müssen angegeben werden.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datenänderungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–30 bis 2–32", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_016", "term": "DELETE", "question": "Wie löscht man bestimmte Zeilen?", "definition": "`DELETE FROM EMPLOYEE WHERE LNAME = 'Brown';` löscht alle passenden Zeilen. Ohne WHERE werden sämtliche Zeilen der Tabelle gelöscht; die Tabelle selbst bleibt bestehen. Fremdschlüsselbedingungen und Referenzaktionen sind zu beachten.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datenänderungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–33 bis 2–34", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_017", "term": "UPDATE", "question": "Wie ändert man Attributwerte vorhandener Zeilen?", "definition": "`UPDATE PROJECT SET PLOCATION = 'Bellaire', DNUM = 5 WHERE PNUMBER = 10;` ändert die ausgewählten Zeilen. Ohne WHERE betrifft die Änderung alle Zeilen. Neue Werte müssen alle Schema- und Referenzbedingungen erfüllen.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Datenänderungen", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–35 bis 2–36", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_018", "term": "SELECT–FROM–WHERE", "question": "Welche Aufgaben haben SELECT, FROM und WHERE?", "definition": "SELECT legt Ausgabeattribute und Ausdrücke fest; FROM die Eingabetabellen; WHERE filtert Kombinationen von Zeilen. Beispiel: `SELECT BDATE, ADDRESS FROM EMPLOYEE WHERE FNAME = 'John' AND LNAME = 'Smith';` Konzeptuell entsprechen sie Projektion, Eingaberelationen und Selektion.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: SELECT und Verbünde", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–37 bis 2–38", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_019", "term": "Verbundbedingung", "question": "Warum braucht eine Anfrage über mehrere Tabellen eine passende Verbundbedingung?", "definition": "`SELECT E.LNAME, D.DNAME FROM EMPLOYEE E, DEPARTMENT D WHERE E.DNO = D.DNUMBER;` kombiniert Angestellte mit ihrer Abteilung. Ohne diese Bedingung entstehen alle Angestellten-Abteilungs-Kombinationen, also ein kartesisches Produkt, sofern andere Bedingungen sie nicht einschränken.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: SELECT und Verbünde", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–39 bis 2–41", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_020", "term": "Qualifizierte Namen und Aliase", "question": "Wie löst man mehrdeutige Spaltennamen und verwendet dieselbe Tabelle mehrfach?", "definition": "Qualifiziere Attribute mit Tabelle oder Alias, etwa `E.SSN`. Für einen Self-Join braucht man getrennte Aliase: `SELECT E.LNAME, S.LNAME FROM EMPLOYEE E, EMPLOYEE S WHERE E.SUPERSSN = S.SSN;`. E und S stehen für unterschiedliche Rollen derselben Tabelle.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: SELECT und Verbünde", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–42 bis 2–45", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_021", "term": "Fehlendes WHERE und SELECT *", "question": "Was bedeuten eine fehlende WHERE-Klausel und SELECT *?", "definition": "Ohne WHERE wird keine Zeile durch eine Suchbedingung ausgeschlossen. Bei mehreren Tabellen bleiben alle Kombinationen. SELECT * gibt alle Spalten der FROM-Quelle aus; `E.*` beschränkt die Ausgabe auf die Spalten des Alias E.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: SELECT und Verbünde", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–46 bis 2–48", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_022", "term": "UNION, INTERSECT und EXCEPT", "question": "Wie verknüpfen UNION, INTERSECT und EXCEPT zwei Anfrageergebnisse?", "definition": "UNION vereinigt, INTERSECT bildet den Schnitt und EXCEPT liefert Zeilen nur aus dem ersten Ergebnis. Die Ergebnisse müssen gleiche Spaltenanzahl und kompatible korrespondierende Typen haben. Diese Operatoren entfernen standardmäßig Duplikate; UNION ALL behält sie.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Mengenoperationen und Ausdrücke", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–51 bis 2–52", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_023", "term": "LIKE", "question": "Wie funktionieren die Platzhalter von LIKE?", "definition": "`%` steht für beliebig viele, auch null Zeichen; `_` für genau ein Zeichen. Beispiel: `WHERE ADDRESS LIKE '%Houston, TX%'` sucht die Zeichenfolge an beliebiger Position. LIKE ist ein Mustervergleich, keine Gleichheitsprüfung.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Mengenoperationen und Ausdrücke", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–53 bis 2–54", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_024", "term": "Arithmetik, Konkatenation und BETWEEN", "question": "Wie verwendet man Berechnungen und BETWEEN in SQL?", "definition": "SELECT kann Ausdrücke wie `1.1 * SALARY` berechnen, ohne gespeicherte Werte zu ändern. `SALARY BETWEEN 30000 AND 40000` schließt beide Grenzen ein. Die Vorlesung verwendet `||` zur Zeichenkettenkonkatenation; Datumsarithmetik arbeitet mit Intervallen.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Mengenoperationen und Ausdrücke", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–55 bis 2–56", "sourceStatus": "ready"},
  {"id": "doc_db_vl01_025", "term": "ORDER BY", "question": "Wie sortiert man ein Anfrageergebnis nach mehreren Attributen?", "definition": "`ORDER BY DNAME ASC, LNAME ASC, FNAME ASC` sortiert zuerst nach Abteilung, bei Gleichheit nach Nach- und Vorname. DESC bedeutet absteigend, ASC aufsteigend und ist die übliche Vorgabe. Ohne ORDER BY besteht keine garantierte Ergebnisreihenfolge.", "subject": "Datenbanken", "topic": "SQL-Grundlagen: Mengenoperationen und Ausdrücke", "note": "DB.pdf • Kapitel 2: SQL – Grundlagen • Folien 2–57 bis 2–58", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_001", "term": "Zweck des ER-Modells", "question": "Wozu dient das ER-Modell, und warum ist es hier kein Datenbankmodell?", "definition": "Es beschreibt fachlich relevante Objekte, Beziehungen, Attribute und Bedingungen unabhängig von einer konkreten Speicherung. In der Vorlesung ist es ein konzeptuelles Entwurfsmodell ohne eigene vollständige Anfragesprache und ohne zugehöriges ER-DBMS. ER-Schemata können in relationale Schemata übersetzt werden.", "subject": "Datenbanken", "topic": "ERM: Grundlagen und Semantik", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–2 bis 3–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_002", "term": "Entität und Entitätenmenge", "question": "Was unterscheidet eine Entität von einer Entitätenmenge?", "definition": "Eine Entität ist ein bestimmtes wahrnehmbares oder gedachtes Objekt, etwa eine konkrete Angestellte. Eine Entitätenmenge fasst Objekte gleichen Typs mit gemeinsamen Eigenschaften zusammen. Im ER-Diagramm wird sie durch ein Rechteck dargestellt.", "subject": "Datenbanken", "topic": "ERM: Grundlagen und Semantik", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_003", "term": "Beziehung und Beziehungsmenge", "question": "Was ist eine Beziehung, und was ist eine Beziehungsmenge?", "definition": "Eine Beziehung verknüpft konkrete Entitäten; eine Beziehungsmenge fasst gleichartige Beziehungen zusammen. Sie wird als Rhombus mit Verbindungen zu beteiligten Entitätenmengen dargestellt. Eigene Attribute, etwa Arbeitsstunden, können Eigenschaften der Beziehung beschreiben.", "subject": "Datenbanken", "topic": "ERM: Grundlagen und Semantik", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–6, 3–17 bis 3–18", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_004", "term": "Trägermenge und aktueller Zustand", "question": "Was bedeuten \\(\\mu(E)\\), \\(\\sigma(E)\\) und \\(\\sigma(A)\\) im ER-Modell?", "definition": "\\(\\mu(E)\\) bezeichnet mögliche Entitäten eines Typs; \\(\\sigma(E)\\subseteq\\mu(E)\\) die endliche Menge aktuell existierender Entitäten. Für ein einfaches obligatorisches Attribut gilt \\(\\sigma(A):\\sigma(E)\\to\\mu(D)\\): Jede aktuelle Entität erhält einen Wert des Wertebereichs.", "subject": "Datenbanken", "topic": "ERM: Grundlagen und Semantik", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–7 bis 3–8", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_005", "term": "Attribut und Attributwert", "question": "Was unterscheidet ein Attribut von einem Attributwert?", "definition": "Ein Attribut ist eine benannte Eigenschaft mit Wertebereich, etwa Name mit Zeichenketten als Domäne. Der Attributwert ist die konkrete Ausprägung bei einer Entität oder Beziehung, etwa 'Meyer'. Attribute werden als Ellipsen dargestellt.", "subject": "Datenbanken", "topic": "ERM: Attribute und Schlüssel", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–6, 3–8", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_006", "term": "Superschlüssel, Kandidat und Primärschlüssel", "question": "Wie unterscheiden sich Superschlüssel, Schlüsselkandidat und Primärschlüssel im ER-Modell?", "definition": "Ein Superschlüssel identifiziert jede Entität eindeutig. Ein Schlüsselkandidat ist ein bezüglich Mengeninklusion minimaler Superschlüssel: Kein Attribut kann weggelassen werden. Ein Kandidat wird als Primärschlüssel gewählt und im Diagramm unterstrichen. Minimal bedeutet nicht zwingend kleinste Anzahl unter allen Kandidaten.", "subject": "Datenbanken", "topic": "ERM: Attribute und Schlüssel", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–9 bis 3–10", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_007", "term": "Schlüssel: Eindeutigkeit und Beispiel", "question": "Was bedeutet die Eindeutigkeitsbedingung eines Schlüssels?", "definition": "Stimmen zwei Entitäten in allen Schlüsselattributen überein, müssen sie dieselbe Entität sein. Formal: \\[\\forall e_1,e_2\\in\\sigma(E):\\ (\\forall A\\in K:\\sigma(A)(e_1)=\\sigma(A)(e_2))\\implies e_1=e_2.\\] ISBN kann ein Buch identifizieren; ein bestimmtes Exemplar benötigt zusätzlich eine Exemplarnummer.", "subject": "Datenbanken", "topic": "ERM: Attribute und Schlüssel", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–10 bis 3–11", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_008", "term": "Komplexe Attribute", "question": "Welche Arten komplexer Attribute behandelt die Vorlesung?", "definition": "Mehrwertig: eine Menge von Werten, etwa Telefonnummern; dargestellt durch Doppelellipse. Abgeleitet: berechnet, etwa Jahresgehalt; gestrichelte Ellipse. Strukturiert: aus Teilattributen zusammengesetzt, etwa Adresse. Optional: darf fehlen; Kreis in der Attributverbindung.", "subject": "Datenbanken", "topic": "ERM: Attribute und Schlüssel", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–12 bis 3–16", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_009", "term": "Arität einer Beziehung", "question": "Was bedeutet die Arität einer Beziehungsmenge?", "definition": "Die Arität zählt beteiligte Rollen: binär zwei, ternär drei, allgemein n-är n. Dieselbe Entitätenmenge kann in mehreren Rollen auftreten. Formal gilt \\(\\sigma(R)\\subseteq\\sigma(E_1)\\times\\cdots\\times\\sigma(E_n)\\).", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–17 bis 3–21", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_010", "term": "Zerlegung n-ärer Beziehungen", "question": "Warum darf man eine ternäre Beziehung nicht immer durch drei binäre Beziehungen ersetzen?", "definition": "Die Paarbeziehungen speichern nicht unbedingt, welche drei Objekte gemeinsam beteiligt waren. Beim Wiederverbinden können zusätzliche, ursprünglich nicht vorhandene Kombinationen entstehen. Eine künstliche Entitätenmenge für die ursprünglichen Beziehungsvorkommen mit binären Verbindungen erhält die gemeinsame Zuordnung.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–22 bis 3–26", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_011", "term": "Rekursive Beziehung und Rollen", "question": "Was ist eine rekursive Beziehung, und wozu dienen Rollennamen?", "definition": "Dieselbe Entitätenmenge beteiligt sich mehrfach. Bei Supervision sind beide Beteiligten Angestellte, aber einer hat die Rolle supervisor und der andere supervisee. Rollennamen verhindern, dass die Bedeutung der Positionen verwechselt wird.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–27 bis 3–28", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_012", "term": "Kardinalitäten 1:1, 1:n und m:n", "question": "Welche Einschränkungen drücken 1:1, 1:n und m:n aus?", "definition": "1:1: Jede Entität ist mit höchstens einer Entität der Gegenseite verbunden. 1:n: Eine Entität der einen Seite kann mehreren der anderen zugeordnet sein, während jede der anderen höchstens einen Partner hat. m:n: Auf beiden Seiten sind mehrere Partner erlaubt. Diese Angaben allein erzwingen keine Teilnahme.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–29 bis 3–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_013", "term": "Min-Max-Kardinalität", "question": "Wie liest man eine (min,max)-Angabe mit Partizipationssemantik?", "definition": "Sie zählt, an wie vielen Beziehungsvorkommen eine bestimmte Entität dieser Rolle beteiligt sein muss beziehungsweise darf. `(1,1)` bedeutet genau einmal, `(0,1)` optional höchstens einmal, `(0,*)` beliebig oft und `(1,*)` mindestens einmal. Die Position hängt von der verwendeten Notation ab; Partizipation und Lookup dürfen nicht verwechselt werden.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–32 bis 3–36", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_014", "term": "Kardinalitäten: Beispiel", "question": "Was bedeutet Professor (1,1) — works_for — Department (1,*)?", "definition": "Jeder Professor gehört genau einem Department an; jedes Department muss mindestens einen Professor haben und darf mehrere haben. Dies liest die Zahlen als Partizipationsangaben bei der jeweiligen Entitätenmenge.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–34", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_015", "term": "Beziehungsattribut verschieben", "question": "Wann kann ein Beziehungsattribut in eine Entitätenmenge verschoben werden?", "definition": "Wenn jede Entität dieser Seite an höchstens einem Beziehungsvorkommen teilnimmt, lässt sich dessen Attribut eindeutig dieser Entität zuordnen. Beispiel: Bei genau einer Arbeitsabteilung pro Person kann der Beginn dieser Zuordnung bei der Person gespeichert werden. Bei mehreren Zuordnungen wäre das mehrdeutig.", "subject": "Datenbanken", "topic": "ERM: Beziehungen und Kardinalitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–32 bis 3–33", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_016", "term": "Schwache Entitätenmenge", "question": "Was ist eine schwache Entitätenmenge?", "definition": "Ihre Entitäten werden erst durch den Schlüssel einer besitzenden Entität zusammen mit einem eigenen Teilschlüssel identifiziert. Jede schwache Entität hat genau einen identifizierenden Besitzer. Notation: doppeltes Rechteck, identifizierende Beziehung als doppelter Rhombus, Teilschlüssel gestrichelt unterstrichen.", "subject": "Datenbanken", "topic": "ERM: Schwache Entitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–37 bis 3–38", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_017", "term": "Schwache Entität: Buchkopie", "question": "Warum ist eine Buchkopie ein Beispiel für eine schwache Entität?", "definition": "Eine Exemplarnummer ist möglicherweise nur innerhalb desselben Buches eindeutig. Erst die Kombination aus ISBN des besitzenden Buches und Exemplarnummer identifiziert eine Kopie global. Ohne das Buch ist der lokale Teilschlüssel nicht ausreichend.", "subject": "Datenbanken", "topic": "ERM: Schwache Entitäten", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–38", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_018", "term": "Spezialisierung", "question": "Was bedeutet Spezialisierung einer Entitätenmenge?", "definition": "Untertypen übernehmen die Eigenschaften und Identität des Obertyps und können weitere Attribute besitzen. Für jeden Zustand gilt \\(\\sigma(E_{\\mathrm{sub}})\\subseteq\\sigma(E_{\\mathrm{super}})\\). Beispielsweise ist jede Technikerin auch eine Angestellte.", "subject": "Datenbanken", "topic": "ERM: Spezialisierung und Entwurf", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–40 bis 3–41", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_019", "term": "Disjunkt oder überlappend", "question": "Was unterscheidet disjunkte von überlappender Spezialisierung?", "definition": "Bei disjunkten Untertypen darf eine Entität höchstens einem dieser Untertypen angehören; Notation d im Kreis. Bei überlappenden Untertypen sind mehrere Zugehörigkeiten erlaubt; Notation o. Dies sagt noch nicht, ob jede Entität überhaupt einem Untertyp angehören muss.", "subject": "Datenbanken", "topic": "ERM: Spezialisierung und Entwurf", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–42, 3–44 bis 3–45", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_020", "term": "Total oder partiell", "question": "Was unterscheidet totale von partieller Spezialisierung?", "definition": "Total: Jede Entität des Obertyps gehört mindestens einem Untertyp an; die Vereinigung der Untertypen ist der Obertyp. Partiell: Es dürfen Entitäten ohne Untertyp existieren. Total wird mit doppelter Verbindung, partiell mit einfacher Verbindung dargestellt. Total/partiell und disjunkt/überlappend sind unabhängig.", "subject": "Datenbanken", "topic": "ERM: Spezialisierung und Entwurf", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–43, 3–46 bis 3–47", "sourceStatus": "ready"},
  {"id": "doc_db_vl02_021", "term": "Vollständiger konzeptueller Entwurf", "question": "Was gehört außer dem ER-Diagramm zu einem vollständigen konzeptuellen Entwurf?", "definition": "Wertebereiche der Attribute, zusätzliche Integritätsbedingungen einschließlich funktionaler und mehrwertiger Abhängigkeiten, vorgesehene Nutzer mit Zugriffsrechten sowie Laufzeitanforderungen. Ein Diagramm allein hält nicht alle fachlichen Regeln fest.", "subject": "Datenbanken", "topic": "ERM: Spezialisierung und Entwurf", "note": "DB.pdf • Kapitel 3: Entity-Relationship-Modell • Folien 3–48", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_001", "term": "Relationenmodell: Grundidee", "question": "Was ist die Grundidee des Relationenmodells?", "definition": "Daten werden einheitlich als mathematische Relationen beschrieben. Die Grundlagen sind Mengen und Prädikatenlogik erster Ordnung. E. F. Codd stellte das Modell 1970 vor. Relation, Tupel und Attribut entsprechen informell Tabelle, Zeile und Spalte.", "subject": "Datenbanken", "topic": "Relationenmodell: Grundlagen und Relationen", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–2 bis 4–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_002", "term": "Wertebereich und dom", "question": "Was sind ein Wertebereich und die Funktion dom?", "definition": "Ein Wertebereich ist eine nichtleere Menge zulässiger Werte mit fachlicher Bedeutung und passender Darstellung. \\(\\operatorname{dom}(A)\\) ordnet Attribut A seine Domäne zu. Gleiche physische Typen bedeuten nicht gleiche fachliche Bedeutung: Gewicht und Preis können beide numerisch sein.", "subject": "Datenbanken", "topic": "Relationenmodell: Grundlagen und Relationen", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–5 bis 4–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_003", "term": "Relationenschema und Relation", "question": "Wie unterscheidet man Relationenschema und Relation formal?", "definition": "Das Schema \\(R(A_1,\\ldots,A_n)\\) beschreibt Namen und Attribute mit Domänen. Ein Zustand ohne NULL ist eine endliche Relation \\[r(R)\\subseteq\\operatorname{dom}(A_1)\\times\\cdots\\times\\operatorname{dom}(A_n).\\] Das Schema beschreibt den Typ; die Relation ist dessen aktuelle Ausprägung.", "subject": "Datenbanken", "topic": "Relationenmodell: Grundlagen und Relationen", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–6 bis 4–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_004", "term": "Grad, Kardinalität und Tupelzugriff", "question": "Was bedeuten Grad, Kardinalität, t[A] und t[X]?", "definition": "Der Grad ist die Attributanzahl n; die Kardinalität \\(|r|\\) ist die Tupelanzahl. \\(t[A]\\) beziehungsweise \\(t.A\\) liefert einen Attributwert; \\(t[X]\\) die Wertekombination für eine Attributmenge X. Eine leere Relation hat Kardinalität null, ihr Grad bleibt durch das Schema festgelegt.", "subject": "Datenbanken", "topic": "Relationenmodell: Grundlagen und Relationen", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–6 bis 4–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_005", "term": "Eigenschaften einer Relation", "question": "Welche Ordnung und welche Duplikate sind in einer Relation erlaubt?", "definition": "Eine Relation ist eine Menge: Tupel haben keine relevante Reihenfolge und identische Tupel kommen nicht mehrfach vor. Bei benannten Attributen darf man Spalten samt zugehörigen Werten gemeinsam umordnen. Jedes Tupel enthält genau einen Wert pro Attribut; im klassischen 1NF-Modell sind diese Werte atomar.", "subject": "Datenbanken", "topic": "Relationenmodell: Grundlagen und Relationen", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–10 bis 4–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_006", "term": "NULL im relationalen Kontext", "question": "Wofür steht NULL, und was ist es nicht?", "definition": "NULL markiert einen fehlenden, unbekannten oder nicht anwendbaren Wert und ist kein gewöhnlicher Domänenwert. Es ist weder die Zahl null noch die leere Zeichenkette. Die auf Folien behandelte Erweiterung des Relationenmodells lässt NULL zu, sofern Bedingungen es nicht verbieten.", "subject": "Datenbanken", "topic": "Relationenmodell: Schlüssel und Integrität", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–7, 4–12, 4–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_007", "term": "Relationale Schlüsselbedingungen", "question": "Wie definiert man Schlüssel im Relationenmodell?", "definition": "Für einen Superschlüssel K gilt in jedem zulässigen Zustand: \\[\\forall t_1,t_2\\in r:\\ t_1[K]=t_2[K]\\implies t_1=t_2.\\] Ein Kandidat ist ein inklusionsminimaler Superschlüssel, der Primärschlüssel ein ausgewählter Kandidat. Schlüssel gelten als Schemaanforderung für alle zulässigen Zustände, nicht nur zufällig in aktuellen Daten.", "subject": "Datenbanken", "topic": "Relationenmodell: Schlüssel und Integrität", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–15 bis 4–18", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_008", "term": "Schlüssel: Alternativen", "question": "Können Schlüsselkandidaten unterschiedlich viele Attribute haben?", "definition": "Ja. Im Vorlesungsbeispiel Car kann {LicenseNumber} ein Kandidat sein und {EngineSerialNumber, Model} ein anderer. Beide sind minimal, wenn keine echte Teilmenge sie ersetzt. Ein Superschlüssel mit zusätzlichen Attributen ist dagegen nicht minimal.", "subject": "Datenbanken", "topic": "Relationenmodell: Schlüssel und Integrität", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–17", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_009", "term": "Entitätsintegrität und Datenbankschema", "question": "Was besagen Entitätsintegrität und die Gültigkeit eines relationalen Datenbankzustands?", "definition": "Primärschlüsselattribute dürfen nicht NULL sein. Ein Datenbankschema besteht aus Relationenschemata und Integritätsbedingungen. Ein gültiger Datenbankzustand enthält passende Relationen und erfüllt alle Bedingungen, insbesondere Domänen-, Schlüssel- und Fremdschlüsselbedingungen.", "subject": "Datenbanken", "topic": "Relationenmodell: Schlüssel und Integrität", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–18 bis 4–19", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_010", "term": "Referentielle Integrität: formal", "question": "Wie definiert man referentielle Integrität eines Fremdschlüssels?", "definition": "Jeder vorhandene Fremdschlüsselwert muss zu einem Schlüsselwert der referenzierten Relation passen; fehlende Referenzen dürfen nur gemäß den festgelegten NULL-Bedingungen auftreten. Bei einer einspaltigen optionalen Referenz gilt \\[\\forall t\\in r:\\ t[FK]=\\mathrm{NULL}\\ \\lor\\ \\exists u\\in s:\\ t[FK]=u[PK].\\] Selbstreferenzen wie EMPLOYEE.SUPERSSN sind erlaubt.", "subject": "Datenbanken", "topic": "Relationenmodell: Schlüssel und Integrität", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–21 bis 4–22", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_011", "term": "Integrität bei Änderungen", "question": "Was muss bei Insert, Delete, Update und Retrieval beachtet werden?", "definition": "Insert fügt Tupel ein, Delete entfernt sie und Update verändert Werte. Das Ergebnis muss alle Integritätsbedingungen erfüllen; andernfalls wird die Änderung abgelehnt oder eine festgelegte Referenzaktion angewandt. Retrieval liest Daten anhand des Schemas, etwa mit SQL, Algebra oder Kalkül.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–23 bis 4–24", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_012", "term": "Starke Entität in Relation überführen", "question": "Wie wird eine starke Entitätenmenge in das Relationenmodell übersetzt?", "definition": "Sie wird zu einem Relationenschema mit ihren einfachen Attributen. Der gewählte Schlüssel wird Primärschlüssel; die Attributdomänen werden festgelegt. Beispiel: Employee(SSN, BDATE, SEX, ADDRESS, SALARY) mit SSN als Schlüssel. Ziel ist eine kapazitätserhaltende Abbildung.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–25 bis 4–27", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_013", "term": "Schwache Entität in Relation überführen", "question": "Wie wird eine schwache Entitätenmenge relational abgebildet?", "definition": "Erzeuge eine eigene Relation mit Teilschlüssel, Besitzer-Schlüssel und weiteren Attributen. Der Besitzer-Schlüssel ist Fremdschlüssel; zusammen mit dem Teilschlüssel bildet er den Primärschlüssel. Beispiel: BookCopy(ISBN, CopyNo, Condition) mit Schlüssel (ISBN, CopyNo) und ISBN als Fremdschlüssel auf Book.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–28 bis 4–30", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_014", "term": "Funktionale Beziehung relational abbilden", "question": "Wie bildet man eine funktionale Beziehung ohne eigene Beziehungstabelle ab?", "definition": "Speichere den Schlüssel des eindeutigen Partners als Fremdschlüssel auf der Seite, deren Entität höchstens einen Partner hat; auch Beziehungsattribute können dort stehen. Beispiel: EMPLOYEE erhält DNO für seine Abteilung. Optionale Teilnahme benötigt gegebenenfalls NULL. Eine 1:1-Beziehung erfordert zusätzlich die entsprechende Eindeutigkeit des Fremdschlüssels.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–31 bis 4–33", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_015", "term": "Allgemeine Beziehung relational abbilden", "question": "Wie bildet man eine m:n- oder allgemeine n-äre Beziehung ab?", "definition": "Erzeuge eine eigene Relation mit den Schlüsseln aller beteiligten Rollen als Fremdschlüssel und den Beziehungsattributen. Ohne weitere funktionale Einschränkungen identifiziert die Kombination aller Rollen-Schlüssel ein Vorkommen. Beispiel: WORKS_ON(ESSN, PNO, HOURS) mit Primärschlüssel (ESSN, PNO).", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–34 bis 4–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_016", "term": "Strukturierte und mehrwertige Attribute abbilden", "question": "Wie übersetzt man strukturierte und mehrwertige ER-Attribute?", "definition": "Strukturierte Attribute werden durch ihre einfachen Teilattribute ersetzt, etwa Name durch FNAME, MINIT und LNAME. Ein mehrwertiges Attribut erhält eine separate Relation mit Entitätsschlüssel und Einzelwert, etwa DEPT_LOCATIONS(DNUMBER, DLOCATION); beide zusammen identifizieren einen Eintrag.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–36 bis 4–38", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_017", "term": "Abgeleitete und obligatorische Attribute abbilden", "question": "Wie behandelt man abgeleitete und nicht-optionale ER-Attribute?", "definition": "Abgeleitete Werte können durch eine Sicht berechnet oder mit einer passenden Integritätsregel kontrolliert gespeichert werden. Nicht-optionale Attribute erhalten NOT NULL. Die Berechnung sollte nicht unkontrolliert redundante, widersprüchliche Daten erzeugen.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–36, 4–39", "sourceStatus": "ready"},
  {"id": "doc_db_vl03_018", "term": "Spezialisierung relational abbilden", "question": "Welche Abbildung der Spezialisierung verwendet die Vorlesung?", "definition": "Obertyp und jeder Untertyp erhalten eine eigene Relation. Der Schlüssel des Untertyps ist zugleich Fremdschlüssel auf den Obertyp; gemeinsame Attribute stehen nur im Obertyp. Beispiel: Employee(SSN, Address), Instructor(SSN, Course), Manager(SSN, Phone). Disjunktheit und Totalität benötigen gegebenenfalls zusätzliche Bedingungen.", "subject": "Datenbanken", "topic": "Relationenmodell: Änderungen und ER-Transformation", "note": "DB.pdf • Kapitel 4: Relationales Datenbankmodell • Folien 4–40 bis 4–42", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_001", "term": "CODASYL-Netzwerkmodell", "question": "Was kennzeichnet das Netzwerk-Datenmodell der Vorlesung?", "definition": "Es ist ein implementierungsnahes Modell der frühen DBMS-Generation nach CODASYL/DBTG. Daten stehen in logischen Records mit Feldern, Beziehungen in funktionalen Set-Typen. Verknüpfte Listen und Navigation sind zentral; physische Datenunabhängigkeit ist gering.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Konzepte und Darstellung", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–2 bis 5–3", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_002", "term": "ERM, RM und Netzwerkmodell vergleichen", "question": "Wie entsprechen sich die Grundbegriffe von ER-, relationalem und Netzwerkmodell?", "definition": "Entität entspricht Tupel beziehungsweise logischem Record; Entitätenmenge entspricht Relationenschema beziehungsweise Record-Type; Attribut entspricht Attribut beziehungsweise Feld. Eine binäre funktionale Beziehungsmenge wird im Netzwerkmodell als Link oder Set-Type dargestellt.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Konzepte und Darstellung", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–3", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_003", "term": "Bachman-Diagramm", "question": "Wie liest man ein Netzwerkschema als Bachman-Diagramm?", "definition": "Knoten bezeichnen Record-Typen, Kanten Set-Typen. In der Foliennotation zeigt eine Kante vom Member-Typ zum Owner-Typ. Ein Owner kann eine Liste mehrerer Member besitzen; ein Member gehört innerhalb eines konkreten Set-Typs höchstens einem Owner.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Konzepte und Darstellung", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–4 bis 5–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_004", "term": "m:n im Netzwerkmodell", "question": "Wie wird eine m:n-Beziehung im Netzwerkmodell umgesetzt?", "definition": "Durch einen zusätzlichen Record-Typ und zwei funktionale Beziehungen. Beispiel: Enrollment verbindet Student und Course Offer; die Note steht im Enrollment-Record. Jeder Enrollment-Record gehört zu genau einem Studenten und einem Kursangebot.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Konzepte und Darstellung", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–4 bis 5–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_005", "term": "Navigation und System-Record", "question": "Wie erfolgt der Zugriff auf eine Netzwerkdatenbank?", "definition": "Über verkettete Listen von Owner- zu Member-Records und Cursoroperationen wie first, next, prior und last. Der vordefinierte System-Record ermöglicht den Einstieg in die verschiedenen Record-Typen. Es wird navigiert, statt nur ein deklaratives Ergebnis zu beschreiben.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Navigation und Grenzen", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–7 bis 5–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl04_006", "term": "Grenzen des Netzwerkmodells", "question": "Welche Einschränkungen betont die Vorlesung am Netzwerkmodell?", "definition": "Im behandelten Modell darf ein Member nicht zugleich Owner bezüglich desselben Set-Typs sein; direkte rekursive Beziehungen sind so nicht vorgesehen. Programmierer legen Navigationswege und Zugriffsoptimierung fest. Die Nähe zu Speicher- und Zugriffsstrukturen erschwert physische Datenunabhängigkeit.", "subject": "Datenbanken", "topic": "Netzwerkmodell: Navigation und Grenzen", "note": "DB.pdf • Kapitel 5: Netzwerk-Datenmodell • Folien 5–7, 5–10", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_001", "term": "Unteranfrage und IN", "question": "Wie funktioniert IN mit einer Unteranfrage?", "definition": "IN prüft die Zugehörigkeit zu deren Ergebnis. Beispiel: `SELECT LNAME FROM EMPLOYEE WHERE DNO IN (SELECT DNUMBER FROM DEPARTMENT WHERE DNAME = 'Research');`. Die Unteranfrage kann auch mehrere korrespondierende Spalten liefern, etwa für den Vergleich eines (PNO,HOURS)-Paars.", "subject": "Datenbanken", "topic": "SQL-Komplex: Unteranfragen und Mengenvergleiche", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–7 bis 6–10", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_002", "term": "ANY, SOME und ALL", "question": "Was bedeuten Vergleichsoperator ANY, SOME und ALL?", "definition": "`x > ANY (Anfrage)` ist wahr, wenn der Vergleich für mindestens einen Ergebniswert wahr ist; SOME ist synonym. `x > ALL (Anfrage)` verlangt ihn für jeden Ergebniswert. Für eine leere Ergebnismenge ist ANY falsch und ALL wahr. NULL kann UNKNOWN verursachen.", "subject": "Datenbanken", "topic": "SQL-Komplex: Unteranfragen und Mengenvergleiche", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–8, 6–11", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_003", "term": "EXISTS und korrelierte Unteranfrage", "question": "Was prüft EXISTS, und wann heißt eine Unteranfrage korreliert?", "definition": "EXISTS ist wahr, wenn die Unteranfrage mindestens eine Zeile liefert. Korreliert bedeutet, dass sie Werte der äußeren Zeile verwendet. Beispiel: `SELECT E.LNAME FROM EMPLOYEE E WHERE EXISTS (SELECT * FROM DEPENDENT D WHERE D.ESSN = E.SSN);` sucht Angestellte mit Angehörigen.", "subject": "Datenbanken", "topic": "SQL-Komplex: Unteranfragen und Mengenvergleiche", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–12 bis 6–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_004", "term": "UNIQUE-Prädikat", "question": "Was prüft UNIQUE bei einer Unteranfrage in der Vorlesung?", "definition": "Es prüft, ob die Unteranfrage keine doppelten Ergebniszeilen erzeugt. NOT UNIQUE erkennt Duplikate. Das ist ein Anfrageprädikat des behandelten Standards, nicht die UNIQUE-Bedingung einer Tabellendefinition. Seine Unterstützung ist DBMS-abhängig.", "subject": "Datenbanken", "topic": "SQL-Komplex: Unteranfragen und Mengenvergleiche", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–12, 6–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_005", "term": "Explizite Werteliste", "question": "Wie prüft man Zugehörigkeit zu einer festen Werteliste?", "definition": "`SELECT DISTINCT ESSN FROM WORKS_ON WHERE PNO IN (1, 2, 3);` liefert Mitarbeitende, die mindestens an einem der angegebenen Projekte arbeiten. IN erspart die entsprechende OR-Verknüpfung mehrerer Gleichheitsvergleiche.", "subject": "Datenbanken", "topic": "SQL-Komplex: Unteranfragen und Mengenvergleiche", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–15", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_006", "term": "TRUE, FALSE und UNKNOWN", "question": "Warum verwendet SQL dreiwertige Logik?", "definition": "Vergleiche mit unbekannten Werten ergeben meist UNKNOWN: Auch `NULL = NULL` ist nicht TRUE. WHERE behält nur Zeilen mit TRUE; FALSE und UNKNOWN werden ausgeschlossen. Mit IS NULL beziehungsweise IS NOT NULL prüft man fehlende Werte gezielt.", "subject": "Datenbanken", "topic": "SQL-Komplex: NULL und dreiwertige Logik", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–16 bis 6–18", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_007", "term": "Dreiwertige Verknüpfungen", "question": "Welche wichtigen Regeln gelten für UNKNOWN?", "definition": "`NOT UNKNOWN = UNKNOWN`; `TRUE AND UNKNOWN = UNKNOWN`; `FALSE AND UNKNOWN = FALSE`; `TRUE OR UNKNOWN = TRUE`; `FALSE OR UNKNOWN = UNKNOWN`. Deshalb ist `B OR NOT B` bei B = UNKNOWN ebenfalls UNKNOWN und keine allgemeine Tautologie.", "subject": "Datenbanken", "topic": "SQL-Komplex: NULL und dreiwertige Logik", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–17", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_008", "term": "NULL-Falle bei NOT IN", "question": "Warum kann NOT IN mit einer Unteranfrage unerwartet keine Zeilen liefern?", "definition": "Enthält die Vergleichsmenge NULL und gibt es keinen gleichen bekannten Wert, wird der Vergleich UNKNOWN statt TRUE. WHERE verwirft diese Zeile. Eine passend korrelierte NOT-EXISTS-Anfrage oder explizites Ausschließen von NULL kann die beabsichtigte Bedingung ausdrücken. Dies folgt aus der dreiwertigen Logik der Folien.", "subject": "Datenbanken", "topic": "SQL-Komplex: NULL und dreiwertige Logik", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–16 bis 6–18", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_009", "term": "Expliziter JOIN und Spaltenalias", "question": "Wie formuliert man einen inneren JOIN und benennt die Ausgabe um?", "definition": "`SELECT E.LNAME AS EMPLOYEE_NAME, D.DNAME FROM EMPLOYEE E JOIN DEPARTMENT D ON E.DNO = D.DNUMBER;`. ON beschreibt passende Zeilenpaare; AS benennt die Ausgabespalte um. Zusätzliche Filter können in WHERE stehen.", "subject": "Datenbanken", "topic": "SQL-Komplex: JOIN und Umbenennung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–19 bis 6–21", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_010", "term": "NATURAL JOIN", "question": "Wie bestimmt NATURAL JOIN die Verbundattribute?", "definition": "Er vergleicht sämtliche gleichnamigen Spalten beider Eingaben auf Gleichheit und führt sie im Ergebnis zusammen. Deshalb müssen Namen und fachliche Bedeutung zusammenpassen; vorherige Umbenennung kann nötig sein. Unbeabsichtigt gleichnamige Spalten können das Ergebnis verändern.", "subject": "Datenbanken", "topic": "SQL-Komplex: JOIN und Umbenennung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–19, 6–22 bis 6–23", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_011", "term": "Äußerer JOIN", "question": "Wie unterscheiden sich LEFT, RIGHT und FULL OUTER JOIN vom INNER JOIN?", "definition": "INNER JOIN behält nur passende Paare. LEFT OUTER JOIN erhält zusätzlich jede unpassende linke Zeile, RIGHT die rechten und FULL beide Seiten. Fehlende Partnerspalten werden mit NULL ergänzt. Ein LEFT JOIN auf den Vorgesetzten erhält daher auch Angestellte ohne Vorgesetzten.", "subject": "Datenbanken", "topic": "SQL-Komplex: JOIN und Umbenennung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–24 bis 6–25", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_012", "term": "Aggregatfunktionen", "question": "Welche Aggregatfunktionen behandelt SQL, und wie verhalten sie sich bei NULL?", "definition": "COUNT zählt, SUM summiert, AVG mittelt, MIN und MAX bestimmen Grenzen. SUM, AVG, MIN, MAX und COUNT(A) ignorieren NULL in A; COUNT(*) zählt alle Zeilen. Auf leerer Eingabe liefert COUNT null als Zahl 0, während etwa SUM und AVG NULL liefern.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–26 bis 6–29", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_013", "term": "COUNT-Varianten", "question": "Was unterscheidet COUNT(*), COUNT(A) und COUNT(DISTINCT A)?", "definition": "COUNT(*) zählt sämtliche Zeilen. COUNT(A) zählt vorhandene Nicht-NULL-Werte von A einschließlich Wiederholungen. COUNT(DISTINCT A) zählt die verschiedenen Nicht-NULL-Werte. Beispiel A = (5,5,NULL): Die Ergebnisse sind 3, 2 und 1.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–28 bis 6–29", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_014", "term": "GROUP BY", "question": "Wie bildet GROUP BY Gruppen, und was darf SELECT ausgeben?", "definition": "Zeilen mit gleichen Gruppierungswerten bilden eine Gruppe. Beispiel: `SELECT DNO, COUNT(*), AVG(SALARY) FROM EMPLOYEE GROUP BY DNO;`. Im einfachen Vorlesungsschema darf SELECT Gruppierungsattribute und Aggregate enthalten, keine beliebigen ungruppierten Attribute. Nicht jedes Gruppierungsattribut muss ausgegeben werden.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–26, 6–30 bis 6–31", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_015", "term": "WHERE und HAVING", "question": "Wie unterscheiden sich WHERE und HAVING?", "definition": "WHERE filtert einzelne Eingabezeilen vor der Gruppierung; HAVING filtert anschließend ganze Gruppen und kann Aggregate verwenden. Beispiel: `SELECT DNO, COUNT(*) FROM EMPLOYEE WHERE SALARY > 30000 GROUP BY DNO HAVING COUNT(*) > 2;`. Standard-SQL erlaubt auch HAVING über einer impliziten Gesamtgruppe ohne explizites GROUP BY.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–32 bis 6–34", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_016", "term": "INSERT mit SELECT", "question": "Wie fügt man ein Anfrageergebnis in eine Tabelle ein?", "definition": "`INSERT INTO DEPTS_INFO (DNO, NO_OF_EMPS) SELECT DNO, COUNT(*) FROM EMPLOYEE GROUP BY DNO;`. Jede Ergebniszeile wird eingefügt. Anzahl, Reihenfolge und Typen der Ausgabespalten müssen zu den Zielspalten passen; Zielbedingungen gelten weiterhin.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl05_017", "term": "Logische SQL-Auswertungsreihenfolge", "question": "In welcher logischen Reihenfolge versteht man einen SELECT-Block?", "definition": "Als Lernmodell: zuerst FROM/JOIN, dann WHERE, GROUP BY, HAVING, SELECT, DISTINCT und zuletzt ORDER BY. Dies beschreibt die Bedeutung, nicht zwingend den physischen Ausführungsplan. Der Optimierer darf eine gleichwertige Verarbeitung wählen. ORDER BY kann sich auf Ausgabenamen beziehen.", "subject": "Datenbanken", "topic": "SQL-Komplex: Aggregation und Gruppierung", "note": "DB.pdf • Kapitel 6: SQL – Komplexe Anfragen • Folien 6–36", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_001", "term": "Lebenszyklus einer Datenbankanwendung", "question": "Welche Phasen umfasst der Lebenszyklus einer Datenbankanwendung?", "definition": "Systemdefinition, Datenbankentwurf, Implementierung, Laden beziehungsweise Datenkonvertierung, Anwendungskonvertierung, Test und Validierung, Inbetriebnahme sowie Überwachung und Wartung. Der Datenbankentwurf ist eine Phase dieses größeren Lebenszyklus.", "subject": "Datenbanken", "topic": "Entwurf: Entwurfsprozess", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–3 bis 7–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_002", "term": "Ziele und Hauptphasen des Entwurfs", "question": "Welche Ziele und Hauptphasen hat der Datenbankentwurf?", "definition": "Ziele sind vollständige fachliche Anforderungen, verständliche Strukturen und passende Leistung bei vertretbarem Aufwand. Hauptphasen: Anforderungen analysieren, konzeptuell entwerfen, DBMS wählen, logisch abbilden, physisch entwerfen, implementieren und tunen. Rücksprünge und Zielkonflikte sind möglich.", "subject": "Datenbanken", "topic": "Entwurf: Entwurfsprozess", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–5 bis 7–8", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_003", "term": "Anforderungsanalyse", "question": "Wie gewinnt und prüft man Datenbankanforderungen?", "definition": "Untersuche Benutzergruppen, Dokumente, Formulare, Berichte, Geschäftsprozesse und Betriebsumgebung; führe Interviews. Informelle Anforderungen können unvollständig oder widersprüchlich sein. Zu erfassen sind Daten, Beziehungen, Regeln, Transaktionen sowie Leistungs- und Sicherheitsanforderungen.", "subject": "Datenbanken", "topic": "Entwurf: Entwurfsprozess", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–9", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_004", "term": "Konzeptueller Entwurf und Sichtenintegration", "question": "Wie unterscheiden sich zentraler Entwurf und Sichtenintegration?", "definition": "Zentral: Anforderungen zusammenführen und Konflikte vor dem gemeinsamen konzeptuellen Entwurf lösen. Sichtenintegration: zunächst Modelle einzelner Benutzergruppen entwerfen, anschließend integrieren und Modellkonflikte lösen. Parallel zum Schema werden Ein-/Ausgaben und Verhalten der Anwendungen und Transaktionen entworfen.", "subject": "Datenbanken", "topic": "Entwurf: Entwurfsprozess", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–10 bis 7–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_005", "term": "Logischer und physischer Entwurf", "question": "Was unterscheidet logischen Entwurf, physischen Entwurf und Tuning?", "definition": "Logischer Entwurf bildet das fachliche Modell auf das gewählte Datenbankmodell ab, etwa ERM auf Relationen, und berücksichtigt Normalisierung. Physischer Entwurf wählt Speicherstrukturen und Zugriffspfade. Tuning verbessert anhand gemessener Nutzung etwa Indizes oder Anfragen. Indizes können Lesen beschleunigen, erhöhen aber Änderungsaufwand.", "subject": "Datenbanken", "topic": "Entwurf: Entwurfsprozess", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–14 bis 7–17", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_006", "term": "Funktionale Abhängigkeit", "question": "Was bedeutet eine funktionale Abhängigkeit \\(X\\to Y\\)?", "definition": "In jedem zulässigen Zustand bestimmen gleiche X-Werte gleiche Y-Werte: \\[\\forall t_1,t_2\\in r:\\ t_1[X]=t_2[X]\\implies t_1[Y]=t_2[Y].\\] X und Y sind Attributmengen. Es handelt sich um eine fachliche Schemaanforderung; die Umkehrung \\(Y\\to X\\) folgt nicht automatisch.", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–18 bis 7–24", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_007", "term": "FD prüfen: Beispiel", "question": "Wie erkennt man eine Verletzung von \\(\\mathrm{PNUMBER}\\to\\mathrm{PLOCATION}\\)?", "definition": "Zwei Tupel mit gleicher Projektnummer, aber verschiedenen Projektorten verletzen die FD. Beispielsweise (423, Leipzig) und (423, Magdeburg). Gleiche Orte bei verschiedenen Projektnummern sind hingegen erlaubt. Ein einzelner Zustand ohne Gegenbeispiel beweist noch nicht, dass die FD fachlich immer gelten soll.", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–21 bis 7–24", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_008", "term": "FD und Superschlüssel", "question": "Wie erkennt man einen Superschlüssel mithilfe funktionaler Abhängigkeiten?", "definition": "X ist Superschlüssel für R, wenn X alle Attribute von R bestimmt: \\[F\\models X\\to R.\\] Für einen Kandidatenschlüssel muss zusätzlich jede echte Teilmenge von X diese Eigenschaft verlieren. Die Eindeutigkeit muss aus den Schemaanforderungen folgen.", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–20", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_009", "term": "FD-Abschluss und Äquivalenz", "question": "Was bedeuten \\(F^+\\), logische Folgerung und äquivalente FD-Mengen?", "definition": "\\(F\\models X\\to Y\\) bedeutet: Jeder Zustand, der F erfüllt, erfüllt auch diese FD. \\(F^+\\) enthält alle solchen Folgerungen. F und G sind äquivalent, wenn \\(F^+=G^+\\); sie können dabei unterschiedlich viele und unterschiedlich formulierte Abhängigkeiten enthalten.", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–25 bis 7–26", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_010", "term": "Armstrong-Axiome", "question": "Wie lauten die Armstrong-Axiome?", "definition": "Reflexivität: Aus \\(Y\\subseteq X\\) folgt \\(X\\to Y\\). Erweiterung: Aus \\(X\\to Y\\) folgt \\(XZ\\to YZ\\). Transitivität: Aus \\(X\\to Y\\) und \\(Y\\to Z\\) folgt \\(X\\to Z\\). Die Regeln sind korrekt und vollständig für funktionale Abhängigkeiten; XY bedeutet Mengenvereinigung.", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–27 bis 7–29", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_011", "term": "Weitere FD-Regeln", "question": "Welche Regeln folgen aus den Armstrong-Axiomen?", "definition": "Vereinigung: \\(X\\to Y\\) und \\(X\\to Z\\) ergeben \\(X\\to YZ\\). Zerlegung: \\(X\\to YZ\\) ergibt \\(X\\to Y\\) und \\(X\\to Z\\). Pseudotransitivität: \\(X\\to Y\\) und \\(ZY\\to V\\) ergeben \\(XZ\\to V\\).", "subject": "Datenbanken", "topic": "Entwurf: Funktionale Abhängigkeiten", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–29", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_012", "term": "Attributabschluss", "question": "Was ist \\(X_F^+\\), und wie berechnet man ihn?", "definition": "\\(X_F^+=\\{A\\in R\\mid F\\models X\\to A\\}\\). Beginne mit X. Für jede FD \\(Y\\to Z\\), deren linke Seite bereits vollständig enthalten ist, füge Z hinzu. Wiederhole dies bis zum Fixpunkt. Dann gilt \\(F\\models X\\to U\\iff U\\subseteq X_F^+\\); die Berechnung des gesamten \\(F^+\\) ist nicht nötig.", "subject": "Datenbanken", "topic": "Entwurf: Attributabschluss und Schlüssel", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–30 bis 7–32", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_013", "term": "Attributabschluss: Rechenbeispiel", "question": "Berechnen Sie \\(A_F^+\\) für \\(R(A,B,C,D)\\) und \\(F=\\{A\\to B,B\\to C\\}\\).", "definition": "Start: \\(\\{A\\}\\). Mit \\(A\\to B\\) erhält man \\(\\{A,B\\}\\), mit \\(B\\to C\\) schließlich \\(\\{A,B,C\\}\\). D lässt sich nicht hinzufügen. A ist daher kein Superschlüssel; AD bestimmt alle Attribute. Dies ist ein kompaktes Rechenbeispiel zum Verfahren der Folien.", "subject": "Datenbanken", "topic": "Entwurf: Attributabschluss und Schlüssel", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–31 bis 7–32", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_014", "term": "Einen Kandidatenschlüssel finden", "question": "Wie findet man einen Kandidatenschlüssel mithilfe des Attributabschlusses?", "definition": "Beginne mit allen Attributen \\(K=R\\). Prüfe für jedes A in K, ob \\((K\\setminus\\{A\\})_F^+=R\\). Wenn ja, entferne A. Am Ende ist K minimal und damit ein Kandidatenschlüssel. Eine solche Reduktion findet einen Kandidaten, nicht automatisch alle Kandidatenschlüssel.", "subject": "Datenbanken", "topic": "Entwurf: Attributabschluss und Schlüssel", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–88 bis 7–89", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_015", "term": "Schlüssel: Synthesebeispiel", "question": "Welcher Schlüssel ergibt sich für \\(R(A,B,C,D,E,F)\\) mit \\(A\\to C\\), \\(A\\to D\\), \\(BC\\to E\\)?", "definition": "ABF ist ein Kandidatenschlüssel: A liefert C und D, danach liefert BC noch E. A, B und F können nicht aus anderen Attributen hergeleitet werden; jeder Schlüssel muss sie daher enthalten. \\((ABF)^+=R\\).", "subject": "Datenbanken", "topic": "Entwurf: Attributabschluss und Schlüssel", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–84, 7–89", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_016", "term": "Normalisierung und Anomalien", "question": "Wozu normalisiert man ein Datenbankschema?", "definition": "Ziel sind weniger unkontrollierte Redundanzen und weniger Einfüge-, Lösch- und Änderungsanomalien. Man untersucht Abhängigkeiten und zerlegt Schemata nach Normalformkriterien. Dabei muss die ursprüngliche Information rekonstruierbar bleiben; möglichst sollen auch Bedingungen lokal prüfbar sein.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–34 bis 7–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_017", "term": "Drei Änderungsanomalien", "question": "Was sind Einfüge-, Lösch- und Änderungsanomalien?", "definition": "Einfügen: Ein Projekt kann ohne Mitarbeitende nicht gespeichert werden, wenn deren Schlüssel mit erforderlich ist. Löschen: Beim Entfernen des letzten Mitarbeitseintrags verschwinden auch Projektdaten. Ändern: Ein Projektname steht mehrfach und muss überall geändert werden, sonst widersprechen sich die Kopien.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–49 bis 7–51", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_018", "term": "Verbundtreue und Verlustfreiheit", "question": "Wann ist eine Zerlegung verlustfrei beziehungsweise verbundtreu?", "definition": "Wenn für jeden zulässigen Zustand die ursprüngliche Relation genau aus den Projektionen durch natürlichen Verbund rekonstruierbar ist: \\[r=\\pi_{R_1}(r)\\bowtie\\cdots\\bowtie\\pi_{R_n}(r).\\] Es dürfen keine zusätzlichen Tupel entstehen. „Verlust“ bedeutet hier auch Verlust der Information, welche Wertekombinationen zusammengehörten.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–35 bis 7–40", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_019", "term": "Binärer Verlustfreiheitstest", "question": "Wie testet man eine binäre Zerlegung unter funktionalen Abhängigkeiten?", "definition": "Für \\(R=R_1\\cup R_2\\) ist die Zerlegung genau dann verlustfrei, wenn \\[(R_1\\cap R_2)\\to R_1\\in F^+\\quad\\text{oder}\\quad(R_1\\cap R_2)\\to R_2\\in F^+.\\] Die gemeinsamen Attribute müssen also mindestens eine Teilrelation funktional bestimmen.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–36 bis 7–39", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_020", "term": "Verlustfreiheit: Gegenbeispiel", "question": "Warum ist die Zerlegung von R(A,B,C) in AB und BC bei \\(F=\\{A\\to B,C\\to B\\}\\) nicht verlustfrei?", "definition": "Der Schnitt B bestimmt weder AB noch BC. Aus r = {(1,2,5),(2,2,6)} entstehen nach Projektion und Verbund zusätzlich (1,2,6) und (2,2,5). Beide Projektionen verlieren die ursprüngliche Zuordnung zwischen A und C. Mit \\(B\\to C\\) wäre die Zerlegung dagegen verlustfrei.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–37 bis 7–40", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_021", "term": "Abhängigkeitstreue", "question": "Wann ist eine Zerlegung abhängigkeitstreu?", "definition": "Wenn sich alle ursprünglichen FD aus den auf Teilrelationen prüfbaren FD herleiten lassen. Sei \\(F_i=\\{X\\to Y\\in F^+\\mid X\\cup Y\\subseteq R_i\\}\\). Dann gilt \\[(F_1\\cup\\cdots\\cup F_n)^+=F^+.\\] Zur Prüfung der Bedingungen ist dann kein Verbund der Teilrelationen nötig. Dies ist eine andere Eigenschaft als Verlustfreiheit.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–41 bis 7–43", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_022", "term": "Abhängigkeitstreue: Beispiel", "question": "Welche Zerlegung erhält \\(F=\\{A\\to BCD,D\\to B\\}\\) besser: AB/ACD oder ABD/AC?", "definition": "AB und ACD erhalten \\(D\\to B\\) nicht lokal und auch nicht als Folgerung der projizierten FD. ABD und AC erhalten dagegen \\(\\mathrm{A}\\to\\mathrm{BD,}\\) \\(\\mathrm{D}\\to\\mathrm{B}\\) und \\(\\mathrm{A}\\to\\mathrm{C}\\); daraus folgt ganz F. Die zweite Zerlegung ist somit abhängigkeitstreu.", "subject": "Datenbanken", "topic": "Entwurf: Zerlegung und Anomalien", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–42 bis 7–43", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_023", "term": "Erste Normalform", "question": "Wann ist ein Schema in 1NF, und wie beseitigt man eine Wertemenge in einer Zelle?", "definition": "Im klassischen Modell enthält jedes Tupel pro Attribut genau einen atomaren Wert oder zulässiges NULL. Eine Menge von Abteilungsorten in einer Zelle verletzt dies. Erzeuge etwa DEPARTMENT(DNUMBER, DNAME, ...) und DEPT_LOCATIONS(DNUMBER, DLOCATION). Die Bedeutung atomar richtet sich nach dem verwendeten Datenmodell.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–44 bis 7–47", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_024", "term": "Prim- und Nichtprimattribut", "question": "Was ist ein Primattribut beziehungsweise Nichtprimattribut?", "definition": "Ein Primattribut gehört zu mindestens einem Kandidatenschlüssel; ein Nichtprimattribut zu keinem. Entscheidend sind alle Kandidatenschlüssel, nicht nur der ausgewählte Primärschlüssel. Diese Unterscheidung wird für 2NF und 3NF benötigt.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–48", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_025", "term": "Zweite Normalform", "question": "Wann ist ein Schema in 2NF?", "definition": "Es ist in 1NF, und jedes Nichtprimattribut hängt voll funktional von jedem Kandidatenschlüssel ab: Kein solches Attribut darf bereits durch eine echte Teilmenge eines Kandidatenschlüssels bestimmt sein. Sind alle Kandidatenschlüssel einattributig, gibt es keine solche partielle Abhängigkeit.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–48 bis 7–54", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_026", "term": "2NF: Projektmitarbeit normalisieren", "question": "Wie normalisiert man EMP_PROJ(SSN, PNUMBER, HOURS, ENAME, PNAME, PLOCATION)?", "definition": "Unter den FD \\(\\mathrm{SSN}\\to\\mathrm{ENAME,}\\) \\(\\mathrm{PNUMBER}\\to\\mathrm{PNAME,PLOCATION}\\) und \\(\\mathrm{SSN,PNUMBER}\\to\\mathrm{HOURS}\\) zerlegt man in EMP(SSN,ENAME), PROJECT(PNUMBER,PNAME,PLOCATION) und EMP_PROJ(SSN,PNUMBER,HOURS). Namen und Orte hängen nur von Teilen des ursprünglichen zusammengesetzten Schlüssels ab.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–50 bis 7–54", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_027", "term": "Dritte Normalform", "question": "Wann ist ein Schema in 3NF?", "definition": "Für jede in \\(F^+\\) geltende nichttriviale FD \\(X\\to A\\) gilt: X ist Superschlüssel oder A ist Primattribut. Anschaulich verhindert 3NF insbesondere transitive Abhängigkeiten von Nichtprimattributen über Nichtschlüssel. Alle Kandidatenschlüssel müssen berücksichtigt werden.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–55 bis 7–58", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_028", "term": "3NF: Abteilungsdaten auslagern", "question": "Warum zerlegt man EMP_DEPT(SSN, ENAME, DNUMBER, DNAME, DMGRSSN)?", "definition": "Aus \\(\\mathrm{SSN}\\to\\mathrm{DNUMBER}\\) und \\(\\mathrm{DNUMBER}\\to\\mathrm{DNAME,DMGRSSN}\\) folgt eine transitive Abhängigkeit der Abteilungsdaten von SSN. Die Zerlegung in EMPLOYEE(SSN,ENAME,DNUMBER) und DEPARTMENT(DNUMBER,DNAME,DMGRSSN) speichert jede Abteilungsinformation nur an einer Stelle.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–58", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_029", "term": "Boyce-Codd-Normalform", "question": "Wann ist ein Schema in BCNF, und wie unterscheidet sie sich von 3NF?", "definition": "Für jede nichttriviale FD \\(X\\to A\\in F^+\\) muss X ein Superschlüssel sein. Die 3NF-Ausnahme für ein rechtes Primattribut entfällt. Deshalb impliziert BCNF die 3NF; umgekehrt kann ein Schema in 3NF noch BCNF verletzen.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–59 bis 7–65", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_030", "term": "BCNF und Verlust von Abhängigkeitstreue", "question": "Warum kann eine BCNF-Zerlegung Bedingungen verlieren?", "definition": "Beispiel R(A,B,C) mit \\(\\mathrm{AB}\\to\\mathrm{C}\\) und \\(\\mathrm{C}\\to\\mathrm{B}\\). AB und AC sind Kandidatenschlüssel; \\(\\mathrm{C}\\to\\mathrm{B}\\) verletzt BCNF, obwohl 3NF erfüllt ist. Die Zerlegung AC und CB ist verlustfrei, da der Schnitt C die Teilrelation CB bestimmt. \\(\\mathrm{AB}\\to\\mathrm{C}\\) lässt sich aber nicht mehr allein durch lokale FD beider Teilrelationen erzwingen.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–62 bis 7–65", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_031", "term": "BCNF ohne Abhängigkeitsverlust", "question": "Kann eine BCNF-Zerlegung auch abhängigkeitstreu sein?", "definition": "Ja. Bei Stadt(Ort, Bundesland, Ministerpräsident, Einwohner) mit \\(\\mathrm{Bundesland}\\to\\mathrm{Ministerpräsident,}\\) \\(\\mathrm{Ministerpräsident}\\to\\mathrm{Bundesland}\\) und \\(\\mathrm{Ort,Bundesland}\\to\\mathrm{Einwohner}\\) eignet sich Regierung(Bundesland,Ministerpräsident) plus Stadt(Ort,Bundesland,Einwohner). Unter genau diesen Annahmen ist die Zerlegung verlustfrei und abhängigkeitstreu.", "subject": "Datenbanken", "topic": "Entwurf: Normalformen 1NF bis BCNF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–66", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_032", "term": "Mehrwertige Abhängigkeit", "question": "Was bedeutet \\(X\\twoheadrightarrow Y\\)?", "definition": "Bei festem X sind die möglichen Y-Werte unabhängig von den übrigen Attributen \\(Z=R\\setminus(X\\cup Y)\\). Zu Tupeln mit gleichem X müssen auch die über Kreuz kombinierten Y- und Z-Werte vorkommen. Beispiel: Autoren und Versionen eines Buches werden unabhängig kombiniert.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–67 bis 7–69", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_033", "term": "MVD formal und als Beispiel", "question": "Welche Tupel fordert eine MVD auf R(X,Y,Z)?", "definition": "Aus \\((x,y_1,z_1)\\in r\\) und \\((x,y_2,z_2)\\in r\\) müssen auch \\((x,y_1,z_2)\\in r\\) und \\((x,y_2,z_1)\\in r\\) folgen. Bei \\(\\mathrm{ISBN}\\twoheadrightarrow\\mathrm{Autor}\\) und zwei unabhängig vorhandenen Versionen muss jeder Autor mit jeder Version kombiniert sein. „Mehrere Werte vorhanden“ allein reicht als MVD-Nachweis nicht aus.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–68 bis 7–69", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_034", "term": "Triviale MVD und FD", "question": "Wann ist eine MVD trivial, und wie hängen FD und MVD zusammen?", "definition": "\\(X\\twoheadrightarrow Y\\) auf R ist trivial, wenn \\(Y\\subseteq X\\) oder \\(X\\cup Y=R\\). Jede FD \\(X\\to Y\\) impliziert die entsprechende MVD; die Umkehrung gilt nicht. Per Komplementregel folgt aus \\(X\\twoheadrightarrow Y\\) auch \\(X\\twoheadrightarrow R\\setminus(X\\cup Y)\\).", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–70 bis 7–72", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_035", "term": "Inferenzregeln für MVD", "question": "Welche weiteren MVD-Regeln nennt die Vorlesung?", "definition": "Reflexivität: \\(Y\\subseteq X\\implies X\\twoheadrightarrow Y\\). Erweiterung: \\(X\\twoheadrightarrow Y\\implies XZ\\twoheadrightarrow Y\\). Addition vereinigt rechte Seiten; Projektion erlaubt deren Schnitt und Differenz. Transitivität lautet \\(X\\twoheadrightarrow Y,\\ Y\\twoheadrightarrow Z\\implies X\\twoheadrightarrow Z\\setminus Y\\). Diese Regeln sind nicht unverändert mit den FD-Regeln gleichzusetzen.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–70", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_036", "term": "Koaleszenz", "question": "Was besagt die Koaleszenzregel für MVD und FD?", "definition": "Aus \\(X\\twoheadrightarrow Y\\) und \\(Z\\to W\\) folgt \\(X\\to W\\), sofern \\(W\\subseteq Y\\) und \\(Y\\cap Z=\\varnothing\\). Die Regel kombiniert mehrwertige und funktionale Abhängigkeiten; die Voraussetzungen sind wesentlich.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–71", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_037", "term": "Vierte Normalform und Zerlegung", "question": "Wann ist ein Schema in 4NF, und wie zerlegt man eine Verletzung?", "definition": "Für jede nichttriviale MVD \\(X\\twoheadrightarrow Y\\) aus dem Abhängigkeitsabschluss muss X Superschlüssel sein. Eine verletzende MVD ermöglicht die verlustfreie Zerlegung in \\(R_1=X\\cup Y\\) und \\(R_2=X\\cup(R\\setminus Y)\\). 4NF impliziert BCNF; Abhängigkeitstreue ist nicht generell garantiert.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–73 bis 7–76", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_038", "term": "4NF: Buchbeispiel", "question": "Wie beseitigt man unabhängige Autoren-, Versions- und Stichwortkombinationen?", "definition": "Zerlege Buch(ISBN,Titel,Autor,Version,Stichwort,Verlagsname) in Buch(ISBN,Titel,Verlagsname), BAutor(ISBN,Autor), BVersion(ISBN,Version) und BStichwort(ISBN,Stichwort), sofern die genannten MVD gelten. So werden die voneinander unabhängigen Mengen separat gespeichert.", "subject": "Datenbanken", "topic": "Entwurf: Mehrwertige Abhängigkeiten und 4NF", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–67, 7–75", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_039", "term": "Normalformhierarchie", "question": "Welche Implikationen und Garantien gelten zwischen den Normalformen?", "definition": "\\[4\\mathrm{NF}\\implies\\mathrm{BCNF}\\implies3\\mathrm{NF}\\implies2\\mathrm{NF}\\implies1\\mathrm{NF}.\\] 3NF lässt sich verlustfrei und abhängigkeitstreu erreichen. BCNF und 4NF können Abhängigkeitstreue verlieren. Eine höhere Normalform bedeutet nicht automatisch den besten physischen Ausführungsplan.", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–76", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_040", "term": "3NF-Synthesealgorithmus", "question": "Welche Schritte hat der 3NF-Synthesealgorithmus?", "definition": "1. Bestimme eine minimale Überdeckung G der FD. 2. Erzeuge für jede gleiche linke Seite X ein Schema aus X und den zugehörigen rechten Attributen. 3. Enthält keines dieser Schemata einen Kandidatenschlüssel des Gesamtschemas, ergänze eine Schlüsselrelation. Das Ergebnis ist in 3NF, verlustfrei und abhängigkeitstreu.", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–82 bis 7–83", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_041", "term": "Synthese: vollständiges Rechenbeispiel", "question": "Was liefert die Synthese für \\(R(A,B,C,D,E,F)\\) und \\(G=\\{A\\to C,A\\to D,BC\\to E\\}\\)?", "definition": "Gruppiere nach linker Seite: A erzeugt R1(A,C,D), BC erzeugt R2(B,C,E). Keine Teilrelation enthält den Gesamtschlüssel ABF; ergänze R3(A,B,F). Die Schlüsselrelation sichert die Rekonstruierbarkeit des gesamten ursprünglichen Schemas.", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–84", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_042", "term": "Minimale Überdeckung", "question": "Welche drei Bedingungen erfüllt eine minimale Überdeckung?", "definition": "Jede FD hat genau ein rechtes Attribut; keine linke Seite enthält ein entbehrliches Attribut; keine FD ist redundant. Die Überdeckung muss zur ursprünglichen FD-Menge äquivalent sein. Sie ist im Allgemeinen nicht eindeutig.", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–85 bis 7–86", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_043", "term": "Minimale Überdeckung berechnen", "question": "Wie reduziert man eine FD-Menge auf eine minimale Überdeckung?", "definition": "Zerlege rechte Seiten. Entferne links ein Attribut, wenn die verkürzte linke Seite das rechte Attribut weiterhin herleitet. Entferne eine FD, wenn sie aus den übrigen folgt. Nutze Attributabschlüsse für diese Tests und prüfe Redundanzen auf der jeweils aktuellen Menge.", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–86 bis 7–87", "sourceStatus": "ready"},
  {"id": "doc_db_vl06_044", "term": "Minimale Überdeckung: Beispiel", "question": "Reduzieren Sie \\(F=\\{A\\to CD,AB\\to C,BC\\to E,AB\\to E\\}\\).", "definition": "Zerlege \\(\\mathrm{A}\\to\\mathrm{CD}\\) in \\(\\mathrm{A}\\to\\mathrm{C}\\) und \\(\\mathrm{A}\\to\\mathrm{D}\\). \\(\\mathrm{AB}\\to\\mathrm{C}\\) ist durch \\(\\mathrm{A}\\to\\mathrm{C}\\) abgedeckt. \\(\\mathrm{AB}\\to\\mathrm{E}\\) folgt aus \\(\\mathrm{A}\\to\\mathrm{C}\\) und \\(\\mathrm{BC}\\to\\mathrm{E}\\). Eine minimale Überdeckung ist somit \\(G=\\{A\\to C,A\\to D,BC\\to E\\}\\).", "subject": "Datenbanken", "topic": "Entwurf: Synthese und Gesamtüberblick", "note": "DB.pdf • Kapitel 7: Datenbankentwurf und Normalisierung • Folien 7–87", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_001", "term": "Prozedural und deklarativ", "question": "Was unterscheidet prozedurale von deklarativen Anfragesprachen?", "definition": "Prozedural beschreibt, wie das Ergebnis aus Operationen entsteht, etwa relationale Algebra. Deklarativ beschreibt, welche Bedingungen das Ergebnis erfüllt, etwa relationaler Kalkül. Die Vorlesung ordnet SQL als Sprache mit beiden Arten von Elementen ein. Relationen als Ein- und Ausgabe erlauben Schachtelung.", "subject": "Datenbanken", "topic": "DB-Sprachen: Arten von Anfragesprachen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–2 bis 8–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_002", "term": "Anforderungen an Anfragesprachen", "question": "Welche Anforderungen nennt die Vorlesung an Anfragesprachen?", "definition": "Effizient ausführbare Operationen, Vermeidung endloser Berechnungen, möglichst deklarative Formulierung zur automatischen Optimierung sowie Unterstützung der Konzepte des Datenmodells. Die grundlegenden relationalen Sprachen sind keine universellen Programmiersprachen.", "subject": "Datenbanken", "topic": "DB-Sprachen: Arten von Anfragesprachen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_003", "term": "Selektion", "question": "Wie ist die Selektion \\(\\sigma_F(r)\\) definiert?", "definition": "Sie wählt Tupel nach einer Bedingung aus: \\[\\sigma_F(r)=\\{t\\in r\\mid F(t)=\\mathrm{true}\\}.\\] Das Schema bleibt gleich. Beispiel: \\(\\sigma_{\\mathrm{SALARY}>30000}(\\mathrm{EMPLOYEE})\\). Die Bedingung kann Vergleiche mit Konstanten oder Attributen durch UND, ODER und NICHT verknüpfen.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–7 bis 8–11", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_004", "term": "Projektion", "question": "Wie ist die Projektion \\(\\pi_X(r)\\) definiert?", "definition": "Sie wählt Attribute aus: \\[\\pi_X(r)=\\{t[X]\\mid t\\in r\\}.\\] Identische Ergebnistupel werden wegen Mengensemantik entfernt. Beispiel: Nur Nachnamen ausgeben. SQL SELECT ohne DISTINCT übernimmt diese Duplikateliminierung nicht automatisch.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–12 bis 8–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_005", "term": "Selektion und Projektion unterscheiden", "question": "Was verändert Selektion, was Projektion?", "definition": "Selektion filtert Zeilen, behält aber alle Attribute. Projektion reduziert die Attribute und kann durch Duplikateliminierung auch die Tupelzahl verringern. Beispiel: \\(\\pi_{\\mathrm{LNAME}}(\\sigma_{\\mathrm{DNO}=5}(\\mathrm{EMPLOYEE}))\\) liefert die verschiedenen Nachnamen aus Abteilung 5.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–8 bis 8–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_006", "term": "Umbenennung", "question": "Wozu dient \\(\\rho_{S(B_1,\\ldots,B_n)}(r)\\)?", "definition": "Sie benennt Relation und/oder Attribute um, ohne die gespeicherten Werte zu verändern. Sie verhindert Namenskollisionen bei Produkten und ermöglicht getrennte Rollen derselben Relation in Self-Joins. Nach der Umbenennung müssen nachfolgende Ausdrücke die neuen Namen benutzen.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–15 bis 8–16", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_007", "term": "Vereinigungskompatibilität", "question": "Wann sind Relationen für Vereinigung, Schnitt oder Differenz kompatibel?", "definition": "Sie haben gleichen Grad und korrespondierende Attribute mit gleichen beziehungsweise kompatiblen Domänen. Die Zuordnung der Spalten muss stimmen; nötigenfalls wird umbenannt. Es genügt nicht, dass beide Relationen zufällig dieselbe Tupelanzahl haben.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–17 bis 8–23", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_008", "term": "Mengenoperationen auf Relationen", "question": "Wie sind Vereinigung, Schnitt und Differenz von Relationen definiert?", "definition": "Für kompatible r und s gilt: \\[r\\cup s=\\{t\\mid t\\in r\\lor t\\in s\\},\\quad r\\cap s=\\{t\\mid t\\in r\\land t\\in s\\},\\quad r\\setminus s=\\{t\\in r\\mid t\\notin s\\}.\\] Die Differenz ist richtungsabhängig; alle Ergebnisse sind Mengen ohne Duplikate.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–18 bis 8–23", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_009", "term": "Kartesisches Produkt", "question": "Was liefert das kartesische Produkt zweier Relationen?", "definition": "Jede Zeile der ersten wird mit jeder der zweiten kombiniert. Bei \\(|r|=a\\) und \\(|s|=b\\) hat \\(r\\times s\\) genau \\(ab\\) Tupel und den addierten Grad. Gemeinsame Attributnamen werden vorher umbenannt. Eine leere Eingabe erzeugt ein leeres Produkt.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Grundoperationen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–24 bis 8–25", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_010", "term": "Theta-Join und Equijoin", "question": "Wie hängen Theta-Join, Selektion und Produkt zusammen?", "definition": "\\[r\\bowtie_\\theta s=\\sigma_\\theta(r\\times s).\\] Ein Equijoin verwendet ausschließlich Gleichheitsbedingungen. Beispiel: EMPLOYEE mit DEPARTMENT über DNO=DNUMBER. Nur Zeilenpaare mit wahrer Bedingung erscheinen; ein gewöhnlicher Gleichheitsvergleich mit NULL liefert keinen Treffer.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Verbünde", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–26 bis 8–32", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_011", "term": "Natürlicher Verbund", "question": "Was ist der natürliche Verbund zweier Relationen?", "definition": "Er kombiniert Tupel, die in allen gleichnamigen Attributen übereinstimmen, und führt gemeinsame Attribute nur einmal. Beispiel: r(A,B) und s(B,C) liefern ein Schema (A,B,C). Gibt es keine gemeinsamen Attribute, entspricht er dem Produkt. Er setzt fachlich passende gemeinsame Namen voraus.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Verbünde", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–33 bis 8–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_012", "term": "Gesetze des natürlichen Verbunds", "question": "Welche algebraischen Eigenschaften hat der natürliche Verbund?", "definition": "Bei passenden Schemata ist er kommutativ und assoziativ; Attributreihenfolge spielt keine Rolle. Er ist monoton und idempotent: \\(r\\bowtie r=r\\). Die leere Relation ist absorbierend. Diese Gesetze helfen, äquivalente Anfrageausdrücke zu bilden und zu optimieren.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Verbünde", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–35", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_013", "term": "Algebra: Anfrage formulieren", "question": "Wie erhält man die Namen der Mitarbeitenden der Research-Abteilung in relationaler Algebra?", "definition": "Verbinde EMPLOYEE und DEPARTMENT über DNO=DNUMBER, wähle DNAME='Research' und projiziere die Namensattribute: \\[\\pi_{\\mathrm{FNAME,LNAME}}\\bigl(\\sigma_{\\mathrm{DNAME}='Research'}(\\mathrm{EMPLOYEE}\\bowtie_{\\mathrm{DNO=DNUMBER}}\\mathrm{DEPARTMENT})\\bigr).\\] Unterschiedliche Ausführungsfolgen dürfen dasselbe Ergebnis beschreiben.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Verbünde", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–26, 8–36", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_014", "term": "Division", "question": "Welche Frage beantwortet relationale Division?", "definition": "Sie sucht Kandidaten, die mit allen geforderten Partnern verbunden sind. Für r über E und S sowie s über S gilt: \\[r\\div s=\\{u\\in\\pi_E(r)\\mid\\forall v\\in s:\\ (u,v)\\in r\\}.\\] Beispiel: Mitarbeitende, die an jedem geforderten Projekt arbeiten.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Erweiterungen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–37 bis 8–39", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_015", "term": "Division aus Grundoperationen", "question": "Wie lässt sich Division mit Projektion, Produkt und Differenz ausdrücken?", "definition": "Mit \\(E=R\\setminus S\\) gilt \\[r\\div s=\\pi_E(r)\\setminus\\pi_E\\bigl((\\pi_E(r)\\times s)\\setminus r\\bigr).\\] Beginne mit allen Kandidaten, ermittle für sie fehlende Kombinationen und entferne jeden Kandidaten mit mindestens einer Lücke.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Erweiterungen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–38", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_016", "term": "Gruppierung in der erweiterten Algebra", "question": "Was ergänzt Gruppierung mit Aggregation zur relationalen Algebra?", "definition": "Sie teilt eine Relation anhand von Gruppierungsattributen auf und berechnet je Gruppe SUM, AVERAGE, COUNT, MINIMUM oder MAXIMUM. Das Ergebnis enthält Gruppenmerkmale und Aggregatwerte. Vor dem Aggregieren dürfen gleiche einzelne Messwerte nicht bloß wegen Wertgleichheit entfernt werden.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Erweiterungen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–40 bis 8–43", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_017", "term": "Äußerer Verbund in der Algebra", "question": "Wozu benötigt man einen äußeren Verbund?", "definition": "Der gewöhnliche Verbund verliert Zeilen ohne passenden Partner. Der linke äußere Verbund erhält alle linken Zeilen, der rechte alle rechten, der volle beide Seiten. Nicht vorhandene Partnerattribute werden mit NULL ergänzt. Das ist eine Erweiterung der klassischen nullfreien Algebra.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationale Algebra: Erweiterungen", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–44 bis 8–48", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_018", "term": "Tupel- und Bereichskalkül", "question": "Wie unterscheiden sich relationaler Tupel- und Bereichskalkül?", "definition": "Beide beschreiben deklarativ das gewünschte Ergebnis. Im Tupelkalkül stehen Variablen für ganze Tupel, im Bereichskalkül für einzelne Attributwerte. Für den sicheren relationalen Kern besitzen sie die Ausdrucksfähigkeit der relationalen Algebra.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–49 bis 8–54", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_019", "term": "Tupelkalkül: Ausdruck und Atome", "question": "Wie liest man einen Tupelkalkülausdruck?", "definition": "\\(\\{t\\mid\\mathrm{EMPLOYEE}(t)\\land t.\\mathrm{SALARY}>50000\\}\\) liefert Angestelltentupel mit passendem Gehalt. Atome sind Relationszugehörigkeit, Vergleiche zweier Attributwerte oder Vergleiche mit Konstanten. Die Ausgabeliste kann auch ausgewählte Komponenten wie t.FNAME und t.LNAME enthalten.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–50 bis 8–56", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_020", "term": "Freie und gebundene Variablen", "question": "Welche Rolle spielen Quantoren im Tupelkalkül?", "definition": "Freie Variablen bestimmen die Ausgabe. Zusätzliche Hilfsvariablen werden durch Existenz- oder Allquantoren gebunden. \\(\\exists t\\) bedeutet „es gibt ein Tupel“, \\(\\forall t\\) „für jedes Tupel“. Quantorenreichweite und Bindung müssen eindeutig sein.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–57 bis 8–58", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_021", "term": "Nicht-Existenz und Allquantor", "question": "Wie formuliert man „kein zugehöriges Tupel existiert“ korrekt?", "definition": "Für Angestellte ohne Angehörige: \\[\\{e\\mid\\mathrm{EMPLOYEE}(e)\\land\\neg\\exists d\\,(\\mathrm{DEPENDENT}(d)\\land d.\\mathrm{ESSN}=e.\\mathrm{SSN})\\}.\\] Äquivalent: Für alle d gilt \\(\\mathrm{DEPENDENT}(d)\\implies d.\\mathrm{ESSN}\\ne e.\\mathrm{SSN}\\). Eine UND-Verknüpfung statt der Implikation würde fälschlich alle betrachteten Tupel zu Angehörigen erklären.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–58 bis 8–60", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_022", "term": "Unsichere Ausdrücke", "question": "Warum ist \\(\\{t\\mid\\neg\\mathrm{EMPLOYEE}(t)\\}\\) problematisch?", "definition": "Ohne endliche Bereichsbeschränkung umfasst es alle denkbaren Tupel außerhalb der Relation und kann unendlich viele Ergebnisse verlangen. Sichere Anfragen binden relevante Werte an Datenbankrelationen oder vorkommende Konstanten. Der allgemeine Test semantischer Sicherheit ist nach den Folien nicht entscheidbar.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–61", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_023", "term": "Syntaktische Sicherheit", "question": "Wie beschränkt man quantifizierte Variablen syntaktisch sicher?", "definition": "Existenzvariablen werden durch eine positive Relationsbedingung eingeschränkt, etwa \\(\\exists t\\,(R(t)\\land F(t))\\). Allvariablen erhalten eine Implikation, etwa \\(\\forall t\\,(R(t)\\implies F(t))\\), also \\(\\neg R(t)\\lor F(t)\\). Die syntaktische Prüfung ist entscheidbar, aber restriktiver als semantische Sicherheit.", "subject": "Datenbanken", "topic": "DB-Sprachen: Relationaler Kalkül", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–62", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_024", "term": "Relationale Vollständigkeit", "question": "Was bedeutet relationale Vollständigkeit einer Anfragesprache?", "definition": "Sie kann alle Anfragen der grundlegenden relationalen Algebra ausdrücken. Sichere relationale Kalküle und diese Algebra sind gleich mächtig: Jede Anfrage kann in die jeweils andere Darstellung übersetzt werden. Das bedeutet keine allgemeine Berechnungsvollständigkeit.", "subject": "Datenbanken", "topic": "DB-Sprachen: Ausdrucksmächtigkeit und Rekursion", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–63", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_025", "term": "Transitive Hülle", "question": "Warum benötigt die allgemeine transitive Hülle Rekursion?", "definition": "Erreichbarkeit kann Wege beliebiger Länge erfordern. Ein fester Algebraausdruck kann nur eine fest beschränkte Zahl von Selbstverbünden enthalten. Der grundlegende relationale Kern und SQL-92 drücken daher allgemeine transitive Hülle nicht aus; rekursive SQL-Konstrukte ab SQL:1999 erweitern dies.", "subject": "Datenbanken", "topic": "DB-Sprachen: Ausdrucksmächtigkeit und Rekursion", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–64 bis 8–66", "sourceStatus": "ready"},
  {"id": "doc_db_vl07_026", "term": "Rekursive SQL-Anfrage", "question": "Wie berechnet man erreichbare Städte mit einer rekursiven SQL-Anfrage?", "definition": "Beispiel: `WITH RECURSIVE E(nach) AS (SELECT nach FROM Verbindung WHERE von = 'Magdeburg' UNION SELECT V.nach FROM E JOIN Verbindung V ON E.nach = V.von) SELECT nach FROM E;`. Der Anfang liefert direkte Ziele, der rekursive Teil weitere Schritte. UNION entfernt wiederholte Ziele und verhindert bei endlich vielen Städten das endlose Wiederholen von Zyklen.", "subject": "Datenbanken", "topic": "DB-Sprachen: Ausdrucksmächtigkeit und Rekursion", "note": "DB.pdf • Kapitel 8: Datenbanksprachen • Folien 8–65 bis 8–66", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_001", "term": "CREATE VIEW und DROP VIEW", "question": "Wie erzeugt und entfernt man eine SQL-Sicht?", "definition": "`CREATE VIEW EMP AS SELECT SSN, LNAME FROM EMPLOYEE;` definiert eine virtuelle Tabelle durch ihre Anfrage. Weitere SELECT-Anfragen können sie verwenden. `DROP VIEW EMP;` entfernt die Sichtdefinition, nicht die Basisdaten. Eine gewöhnliche Sicht speichert keine eigene dauerhafte Kopie ihres Ergebnisses.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Sichten", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–2 bis 9–8", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_002", "term": "Aggregationssicht", "question": "Wie definiert man eine Sicht mit benannten Aggregatspalten?", "definition": "`CREATE VIEW DEPT_INFO (DNO, NO_OF_EMPS, TOTAL_SAL) AS SELECT DNO, COUNT(*), SUM(SALARY) FROM EMPLOYEE GROUP BY DNO;`. Eine explizite Spaltenliste oder passende Ausgabenamen benennt berechnete Spalten. Die Sicht wird aus dem aktuellen Basiszustand bestimmt.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Sichten", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–5 bis 9–7", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_003", "term": "View-Update-Problem", "question": "Was ist das View-Update-Problem?", "definition": "Eine Änderung der virtuellen Ergebnistabelle muss auf Basisdaten zurückgeführt werden. Bei Aggregationen und Verbünden ist diese Übersetzung häufig mehrdeutig: Ein höheres Gesamtgehalt sagt beispielsweise nicht, welche Einzelgehälter zu ändern sind. Darum ist nicht jede Sicht allgemein aktualisierbar.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Sichten", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–9 bis 9–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_004", "term": "Aktualisierbare Sicht", "question": "Welche einfache aktualisierbare Sicht behandelt die Vorlesung?", "definition": "Eine Sicht auf eine einzelne Basistabelle ohne Aggregation, deren Ausgabe einen eindeutigen Schlüssel enthält, etwa EMP(SSN,LNAME,FNAME). Ein UPDATE über SSN lässt sich eindeutig auf EMPLOYEE übertragen. Die genauen unterstützten Änderungsfälle richten sich nach DBMS und Sichtdefinition.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Sichten", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–9 bis 9–10", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_005", "term": "WITH CHECK OPTION", "question": "Wozu dient WITH CHECK OPTION bei einer Auswahlsicht?", "definition": "Es verhindert Änderungen über die Sicht, nach denen eine betroffene Zeile ihre Sichtbedingung nicht mehr erfüllt. Beispiel: Eine Sicht auf Abteilung 5 darf mit dieser Option nicht durch ein UPDATE DNO=4 eine Zeile aus ihrem eigenen sichtbaren Bereich verschieben.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Sichten", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–14 bis 9–15", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_006", "term": "Account- und Objektprivilegien", "question": "Welche Ebenen von Berechtigungen unterscheidet die Vorlesung?", "definition": "Accountbezogene Rechte erlauben etwa das Erzeugen oder Ändern von Datenbankobjekten. Objektbezogene Rechte regeln SELECT, INSERT, UPDATE und DELETE auf bestimmten Tabellen oder Sichten. Der DBA verwaltet Accounts und Rechte; ein Objektbesitzer verfügt über die zugehörigen Verwaltungsrechte.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: Privilegien und Autorisierung", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–16 bis 9–17", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_007", "term": "GRANT und WITH GRANT OPTION", "question": "Wie vergibt man Rechte, und was erlaubt WITH GRANT OPTION?", "definition": "`GRANT SELECT ON EMPLOYEE TO A3 WITH GRANT OPTION;` erteilt Leserecht und erlaubt dessen Weitergabe. Ohne diese Option kann A3 das Recht nutzen, aber nicht auf dieser Grundlage weitervergeben. PUBLIC bezeichnet alle entsprechenden Benutzeraccounts, nicht anonymen Zugriff außerhalb des DBMS.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: Privilegien und Autorisierung", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–18 bis 9–20", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_008", "term": "Rechte über eine benutzerspezifische Sicht", "question": "Wie können Sichten den sichtbaren Datenbereich einschränken?", "definition": "Definiere etwa eine Sicht MYORDER mit `WHERE CUSTOMER_NAME = USER` und erteile SELECT nur auf diese Sicht. Der Zugriff auf Basistabellen darf die Einschränkung nicht umgehen. USER steht in der Folie für den aktuellen Datenbankbenutzer.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: Privilegien und Autorisierung", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–19", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_009", "term": "REVOKE, RESTRICT und CASCADE", "question": "Wie nimmt man Rechte zurück, und was geschieht mit weitergegebenen Rechten?", "definition": "`REVOKE SELECT ON EMPLOYEE FROM A3 RESTRICT;` scheitert im behandelten Fall, wenn abhängige Weitergaben bestehen. CASCADE nimmt davon abhängige Weitergaben ebenfalls zurück. Unabhängig über andere gültige Vergabewege bestehende Rechte müssen dabei unterschieden werden.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: Privilegien und Autorisierung", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–21 bis 9–24", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_010", "term": "SQL-Injektion: Ursache und Beispiel", "question": "Wie entsteht SQL-Injektion?", "definition": "Eine Anwendung baut SQL durch unkontrolliertes Einsetzen von Nutzereingaben zusammen. Dann kann Eingabe als SQL-Code statt als Daten interpretiert werden. Im Folienbeispiel wird an eine Produktabfrage ein zusätzlicher unerwünschter UPDATE-Befehl angehängt.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Injektion", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–25 bis 9–27", "sourceStatus": "ready"},
  {"id": "doc_db_vl08_011", "term": "SQL-Code und Eingabedaten trennen", "question": "Wie verhindert man, dass Nutzereingaben als SQL-Code wirken?", "definition": "Verwende parametrisierte Anfragen, etwa `SELECT * FROM produkt WHERE PNr = ?`, und binde den Wert getrennt. Validierung und minimale Datenbankrechte ergänzen dies. Die Folien beschreiben auch Escaping; bloßes manuelles Zusammensetzen und Maskieren ist fehleranfällig und ersetzt Parameterbindung nicht.", "subject": "Datenbanken", "topic": "Sichten und Sicherheit: SQL-Injektion", "note": "DB.pdf • Kapitel 9: SQL – Sichten und Sicherheit • Folien 9–25 bis 9–27", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_001", "term": "Grundidee von QBE", "question": "Was bedeutet Query By Example, und wie stellt man eine Anfrage?", "definition": "Man trägt Beispielelemente, Konstanten und Bedingungen in Tabellengerüste ein. Die Darstellung orientiert sich an den gewünschten Daten statt an einem textuellen Ablaufprogramm. QBE ist ein Vorläufer tabellenbasierter Abfrageoberflächen.", "subject": "Datenbanken", "topic": "QBE: Anfragegerüste und Variablen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–2 bis 10–4", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_002", "term": "P. und Beispielelemente", "question": "Was bedeuten P., _x und leere Felder in QBE?", "definition": "P. markiert auszugebende Werte. Ein Beispielelement wie `_x` bezeichnet eine Bereichsvariable; wiederholte Verwendung verlangt denselben Wert. Leere Einträge stehen für jeweils eigene, nicht ausgegebene Variablen. Konstanten wie Informatik und Vergleiche wie >2 schränken die Zeilen ein.", "subject": "Datenbanken", "topic": "QBE: Anfragegerüste und Variablen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–3 bis 10–4, 10–13", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_003", "term": "Verbund und Self-Join in QBE", "question": "Wie drückt QBE einen Verbund oder Self-Join aus?", "definition": "Trage dasselbe Beispielelement in die zu vergleichenden Spalten verschiedener Tabellenzeilen ein. Das erzwingt Gleichheit und verbindet die Zeilen. Mehrere Gerüstzeilen derselben Tabelle mit geteilten Variablen erlauben den Vergleich verschiedener Rollen derselben Relation.", "subject": "Datenbanken", "topic": "QBE: Anfragegerüste und Variablen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–4, 10–7, 10–16", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_004", "term": "Condition Box", "question": "Wozu dient die Condition Box in QBE?", "definition": "Sie formuliert zusätzliche Bedingungen über Beispielelemente, etwa `_St = 'Informatik' OR _St = 'Mathematik'`. Bedingungen in einer gemeinsamen Zeilenkombination werden mit den positiven Tabellenbedingungen verknüpft. Mehrere Gerüstzeilen sind nicht ohne Betrachtung der Ausgabe- und Variablenbindung pauschal als OR zu lesen.", "subject": "Datenbanken", "topic": "QBE: Bedingungen, Ausgabe und Aggregation", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–5 bis 10–6", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_005", "term": "Eigene Ausgabetabelle", "question": "Wann verwendet man eine temporäre Ausgabetabelle in QBE?", "definition": "Wenn die Ausgabe Spalten mehrerer Tabellen kombiniert oder andere Namen beziehungsweise Reihenfolge benötigt. Beispielsweise kann Info_VL(Name,Voraussetzung,SWS,Semester) Variablen aus Vorl und Vorl_Voraus mit P. ausgeben.", "subject": "Datenbanken", "topic": "QBE: Bedingungen, Ausgabe und Aggregation", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–8", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_006", "term": "Negierte Zeile", "question": "Was bedeutet eine negierte Zeile in QBE?", "definition": "Es darf kein Tupel existieren, das diese Zeilenbedingungen mit den bereits gebundenen Variablen erfüllt. Beispiel: Eine Vorlesung hat maximale SWS, wenn keine Vorlesung mit größerem SWS-Wert existiert. Das entspricht einer negierten Existenzquantifizierung.", "subject": "Datenbanken", "topic": "QBE: Bedingungen, Ausgabe und Aggregation", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–9, 10–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_007", "term": "Sortierung in QBE", "question": "Wie wird eine mehrstufige Sortierung in der gezeigten QBE-Notation angegeben?", "definition": "AO. kennzeichnet aufsteigende Sortierung; die Zahl in Klammern legt die Priorität fest. Im Folienbeispiel bedeutet AO(1). beim Studiengang und AO(2). beim Semester: zuerst Studiengang, innerhalb davon Semester.", "subject": "Datenbanken", "topic": "QBE: Bedingungen, Ausgabe und Aggregation", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–10", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_008", "term": "Aggregation in QBE", "question": "Wie liest man P.SUM.ALL. und P.CNT.UN.ALL.?", "definition": "P. gibt aus, SUM. summiert und CNT. zählt. ALL. bezieht alle passenden Vorkommen ein; UN. beschränkt dabei auf unterschiedliche Werte. Im Buch-Autor-Beispiel zählt P.CNT.UN.ALL. die verschiedenen Autoren. Die Bedeutung folgt der auf den Folien verwendeten QBE-Variante.", "subject": "Datenbanken", "topic": "QBE: Bedingungen, Ausgabe und Aggregation", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–11 bis 10–12", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_009", "term": "QBE und Bereichskalkül", "question": "Wie wird eine QBE-Anfrage formal interpretiert?", "definition": "Jede positive Tabellenzeile liefert ein Relationsatom mit ihren Konstanten, Variablen und Vergleichen. Wiederholte Variablen verknüpfen die Atome. Nicht ausgegebene Variablen werden existenziell gebunden; negative Zeilen werden zu negierten Existenzbedingungen. Hinzu kommen Bedingungen aus der Condition Box.", "subject": "Datenbanken", "topic": "QBE: Formale Semantik und Änderungen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–13 bis 10–14", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_010", "term": "Ausdrucksfähigkeit von QBE", "question": "Ist eine einzelne QBE-Anfrage im behandelten Modell relational vollständig?", "definition": "Nein. Die beschriebene Quantorenstruktur erlaubt keine beliebige Existenzquantifizierung nach Allquantoren. Eine Folge von QBE-Anfragen mit Zwischenergebnissen ist dagegen relational vollständig. Projektion entspricht P., Selektion Bedingungen, Verbund geteilten Beispielelementen.", "subject": "Datenbanken", "topic": "QBE: Formale Semantik und Änderungen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–15 bis 10–16", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_011", "term": "I., D. und U.", "question": "Wie stellt QBE Einfügen, Löschen und Ändern dar?", "definition": "I. kennzeichnet einzufügende Zeilen, D. zu löschende und U. neue Werte einer Änderung. Beispiel: Mit D. und Kto<0 werden Kunden mit negativem Kontostand ausgewählt und gelöscht. Zum Senken eines Kontostands wird der alte Wert gebunden und als neuer Wert `_AlterWert - 100` angegeben.", "subject": "Datenbanken", "topic": "QBE: Formale Semantik und Änderungen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–17 bis 10–20", "sourceStatus": "ready"},
  {"id": "doc_db_vl09_012", "term": "Einfügen aus einer anderen Relation", "question": "Wie fügt man in QBE Daten aus einer Quelltabelle ein?", "definition": "Binde Beispielelemente in der Quelltabelle und verwende sie in einer mit I. markierten Zielzeile. Das Vorlesungsbeispiel übernimmt Lieferantennamen und -adresse als Kundendaten und setzt den Kontostand auf 0. Das entspricht konzeptuell INSERT mit SELECT.", "subject": "Datenbanken", "topic": "QBE: Formale Semantik und Änderungen", "note": "DB.pdf • Kapitel 10: Query By Example • Folien 10–18", "sourceStatus": "ready"}
]);

